    // A short history, expressed in a coordinate frame pointing toward the
    // observer. The side axis is reflected with lateral speed. Distances and
    // terrain samples are local; the regression uses no map or seat identity.
    bool forecastDuel(const Obs &o,int k,int f,int delay){
        if(duelEnemy<0 || !o.p[k].vis || f<10)return false;
        Actor &e=actor[k];auto &p=o.p[k];auto &observer=history[f%HISTORY];
        const auto &dart=o.d[k], &incoming=histD[f%HISTORY];
        V here=pos(p),to=pos(observer)-here,axis=to.unit(),side=axis.side();
        if(to.len()>11000 || to.len()<300)return false;
        double sign=vel(p).dot(side);if(std::abs(sign)<30)sign=(home-here).dot(side);
        if(sign<0)side=side*(-1);
        double x[35]{};int count=0;
        auto add=[&](double a){x[count++]=a;};
        auto vector=[&](V v){add(v.dot(axis));add(v.dot(side));};
        add(to.len());add(p.st);add(p.timer);add(p.cd);add(dart.st);add(incoming.st);
        add(observer.st);add(observer.timer);add(p.expose);vector(vel(p));vector(vel(observer));
        for(int a:{3,7}){
            const auto &past=trail[k][(f-a)%TRAIL];
            vector(past.frame==f-a?(here-past.p)*(1./a):vel(p));
        }
        vector(dart.st!=D_HAND?pos(dart)-here:V{});
        vector(incoming.st!=D_HAND?pos(incoming)-here:V{});
        vector(home-here);vector({double(p.ax),double(p.ay)});add(dart.left);add(std::min<i64>(16,dart.age));
        for(V a:{axis,axis*(-1),side,side*(-1),(axis+side)*.707,(axis-side)*.707,(side-axis)*.707,(axis+side)*(-.707)}){
            int mask=0,bit=1;
            for(int length:{650,1400,2550}){int tile=cell(here+a*length,5-delay);if(tile!=C_PIT && tile!=C_WALL)mask|=bit;bit*=2;}
            add(mask);
        }
        const short *paths[5];V mean[6]{};
        for(int m=0;m<5;m++){
            int j=motionRoots[m];
            while(motionNodes[j].feature>=0){
                auto &node=motionNodes[j];
                j=x[node.feature]<=node.threshold?node.left:node.right;
            }
            paths[m]=motionLeaf[motionNodes[j].left];
            for(int a=1;a<=5;a++)mean[a]=mean[a]+(axis*paths[m][2*a-2]+side*paths[m][2*a-1])*.20;
        }
        int lo=0,hi=0;
        for(int m=1;m<5;m++){if(paths[m][5]<paths[lo][5])lo=m;if(paths[m][5]>paths[hi][5])hi=m;}
        for(int model=13;model<16;model++){
            V delta[6]{};
            for(int a=1;a<=5;a++){int m=model==14?lo:hi;delta[a]=model==13?mean[a]:axis*paths[m][2*a-2]+side*paths[m][2*a-1];}
            for(int h=0;h<=H;h++){
                double phase=std::min(5.,(h+delay)*.25);
                int lower=int(phase);double part=phase-lower;
                V q=here+delta[lower]*(1.-part)+delta[std::min(5,lower+1)]*part;
                if(h<e.freeAfter && p.st!=S_DASH && p.st!=S_RECALL)q=e.path[0][h];
                if(cell(q,h)==C_WALL || (cell(q,h)==C_PIT && p.st!=S_DASH && p.st!=S_STUN))q=e.path[0][h];
                e.path[model][h]=q;e.modelHand[model][h]=e.modelHand[0][h];
            }
        }
        return true;
    }
    void matchMotion(const Obs &o,int k,int f,int delay){
        Actor &e=actor[k]; trajectoryWeight[k]=0;
        for(int m=10;m<NMODEL;m++)std::copy(e.path[0],e.path[0]+H+1,e.path[m]);
        if(o.p[k].st!=S_FREE || !o.p[k].vis || f<30 || n>4)return;
        struct Sample {double score;int at;};
        std::vector<Sample> samples;
        auto frame=[&](int j)->const Footstep&{return trail[k][j%TRAIL];};
        const auto &cur=frame(f);
        for(int j=std::max(10,f-TRAIL+12);j<=f-H-delay;j++){
            const auto &old=frame(j);
            if(old.frame!=j || old.state!=cur.state || old.dart!=cur.dart)continue;
            if(frame(j+H+delay).frame!=j+H+delay)continue;
            double diff=0;
            for(int lag:{0,2,5,8}){
                const auto &a=frame(f-lag),&b=frame(j-lag);
                if(a.frame!=f-lag || b.frame!=j-lag){diff+=4000;continue;}
                diff+=(a.v-b.v).len()*(lag==0?1.5:.72);
                diff+=((cur.p-a.p)-(old.p-b.p)).len()*.19;
            }
            diff+=(cur.p-old.p).len()*.23;
            diff+=((cur.p-cur.observer)-(old.p-old.observer)).len()*.13;
            diff+=(f-j)*.70;
            if(diff<1650)samples.push_back({diff,j});
        }
        std::sort(samples.begin(),samples.end(),[](Sample a,Sample b){return a.score<b.score;});
        int used[3]{},count=0;double quality=0;
        for(auto sample:samples){
            bool ok=true;for(int z=0;z<count;z++)if(std::abs(sample.at-used[z])<4)ok=false;
            if(!ok)continue;
            const auto &start=frame(sample.at);
            for(int h=0;h<=H;h++){
                auto &next=frame(sample.at+h+delay);
                V pred=cur.p+next.p-start.p;
                if(next.frame!=sample.at+h+delay || (cell(pred,h)==C_PIT && next.state!=S_DASH && next.state!=S_STUN)){ok=false;break;}
                e.path[10+count][h]=pred;
            }
            if(!ok)continue;
            used[count++]=sample.at;
            quality+=std::exp(-sample.score/620.);
            if(count==3)break;
        }
        if(count){
            for(int m=count;m<3;m++)std::copy(e.path[10],e.path[10]+H+1,e.path[10+m]);
            trajectoryWeight[k]=0.86*quality/count;
        }
    }
