    static constexpr int threatRoots[]={0,391,748,1119,};

    double shotEvidence[MAXP][MAXP]{};
    double focusShot(const Obs &o,int k,int j,int delay,const V location[])const{
        const auto &p=memory[k],&q=j==s?history[(t-delay)%HISTORY]:memory[j];
        const auto &d=o.d[k],&dq=j==s?histD[(t-delay)%HISTORY]:o.d[j];
        V pk=location[k],qj=location[j],axis=(qj-pk).unit();double r=(qj-pk).len();
        double d1=30000,d2=30000;int count=1;
        for(int u=0;u<n;u++)if(u!=k && u!=j && (u==s || actor[u].valid)){
            d1=std::min(d1,(location[u]-pk).len());d2=std::min(d2,(location[u]-qj).len());count++;
        }
        double x[28];int idx=0;auto add=[&](double val){x[idx++]=val;};
        auto player=[&](const Player &z,const Dart &dart){
            add(z.st);add(std::min<i64>(14,z.timer));add(std::min<i64>(20,z.cd));add(dart.st);
            add(vel(z).len());add(vel(z).dot(axis));add(std::abs(vel(z).dot(axis.side())));
            add(V{double(z.ax),double(z.ay)}.dot(axis));
        };
        add(r);add(d1);add(d2);add(r-d1);add(r-d2);add(count);player(p,d);player(q,dq);
        add(cell(qj,-delay)==C_GRASS && !q.expose);add(los(pk,qj));add((qj-pos(dq)).len());add(dq.left);add(std::min<i64>(25,dq.age));add(p.kills-q.kills);
        double sum=0;
        for(int root:threatRoots){
            int z=root;while(threatTree[z].feature>=0){const auto &b=threatTree[z];z=x[b.feature]<=b.cut?b.left:b.right;}
            sum+=threatTree[z].left/4000.;
        }
        return sum;
    }
    void inferTargets(const Obs &o,int delay){
        V location[MAXP];
        for(int j=0;j<n;j++)location[j]=j==s?pos(history[(t-delay)%HISTORY]):actor[j].oldpos;
        for(int k=0;k<n;k++)if(k!=s && actor[k].valid){
            const Player &p=memory[k];
            double total=0,best=-1;preferredEnemy[k]=s;
            for(int j=0;j<n;j++){
                attention[k][j]=0;
                if(j==k || (j!=s && !actor[j].valid) || info().team[k]==info().team[j])continue;
                V d=location[j]-location[k];double length=d.len();
                const Player &other=j==s?history[(t-delay)%HISTORY]:memory[j];
                const Dart &weapon=j==s?histD[(t-delay)%HISTORY]:o.d[j];
                bool hidden=length>cf.see_r && !other.expose && cell(location[j],-delay)==C_GRASS &&
                         !dart_flying(weapon.st) && weapon.st!=D_RISE;
                double value=std::exp(-length/2250.);
                if(hidden)value*=.12;
                if(!los(location[k],location[j]))value*=.44;
                bool attacking=p.st==S_THROW || p.st==S_SLASH || p.st==S_KICK || p.st==S_DASH;
                if(attacking)value*=std::exp(1.5*V{p.ax*.001,p.ay*.001}.dot(d.unit()));
                if(weapon.st!=D_HAND)value*=1.28;
                if(cf.mode==1 && aliveEnemies>=2 && p.vis){
                    double pred=focusShot(o,k,j,delay,location);
                    shotEvidence[k][j]=pred;
                    double odds=clip(pred/(1.02-pred),.025,6.);
                    value*=std::pow(odds/.18,0.35);
                }
                attention[k][j]=value;total+=value;
                if(value>best){best=value;preferredEnemy[k]=j;}
            }
            if(total>0)for(int j=0;j<n;j++)attention[k][j]/=total;
        }
    }
    std::vector<double> armedMass[MAXP];
    void predict(const Obs &o){
        if(duelEnemy>=0)armedMass[duelEnemy].assign(H+cf.delay+1,0.);
        for(auto &v:flights)v.clear();
        aliveEnemies=0; target=-1; double near=1e10;
        int delay=std::min<int>(t,cf.delay);
        Game base(info(),o);
        base.t=t-delay;
        base.p[s]=history[(t-delay)%HISTORY]; base.p[s].team=info().team[s];
        base.d[s]=histD[(t-delay)%HISTORY];
        for(int k=0;k<n;k++)if(k!=s){
            auto &e=actor[k]; const auto &p=o.p[k];
            e.valid=p.alive;e.enemy=info().team[k]!=info().team[s];
            if(!p.alive)continue;
            if(e.enemy)aliveEnemies++;
            if(p.vis){
                int stamp=t-delay;
                trail[k][stamp%TRAIL]={pos(p),vel(p),pos(history[stamp%HISTORY]),stamp,int(p.st),int(o.d[k].st)};
                grass[k].at=-1;grass[k].cells.clear();
                V v=vel(p);
                if(t-delay>lastSeen[k]){
                    if(p.st==S_DASH && memory[k].st!=S_DASH){
                        enemyDashes[k]++;
                        double gap=(pos(p)-pos(history[stamp%HISTORY])).len();
                        if(gap>cf.dash_v*cf.dash_t+reach+1200)travelDash[k]=true;
                    }
                    if(p.st==S_FREE && (pos(p)-pos(memory[k])).len()<30)stillTime[k]++;else stillTime[k]=0;
                }
                if(lastSeen[k]!=t-delay-1 || p.st!=S_FREE)v={};
                if(lastSeen[k]==t-delay-1 && p.st==S_FREE)
                    avgMove[k]=avgMove[k]*.66 + v*.34;
                else avgMove[k]=v;
                if(t-delay>lastSeen[k] && p.st==S_THROW && memory[k].st!=S_THROW){
                    enemyShotCount[k]++;
                    double range=(pos(p)-pos(history[std::max(0,t-delay)%HISTORY])).len();
                    farShot[k]=std::max(farShot[k],range);
                    const Player &seen=history[std::max<int>(0,t-2*delay-1)%HISTORY];
                    V origin=pos(p),dir=V{double(p.ax),double(p.ay)}.unit();
                    for(int b=0;b<5;b++){
                        V pred=pos(seen)+vel(seen)*(3.25*b);
                        double err=std::abs((pred-origin).dot(dir.side()));
                        leadFit[k][b]=.7*leadFit[k][b]+.3/(1+err*err/(400.*400.));
                    }
                }
                memory[k]=p;lastSeen[k]=t-delay;
                auto &f=pastForecast[k][(t-delay)%HISTORY];
                if(f.at==t-delay && f.category>=0){
                    for(int m=0;m<NMODEL;m++){
                        double error=(f.value[m]-pos(p)).len();
                        double quality=1./(1.+error*error/(600.*600.));
                        double &ema=skill[k][f.category][m];
                        ema=.94*ema+.06*quality;
                    }
                }
            }
            e.hidden=!p.vis;
            if(e.hidden){
                trackGrass(k,t-delay,pos(history[(t-delay)%HISTORY]));
                base.p[k]=memory[k]; auto &b=base.p[k];
                b.team=info().team[k];b.alive=1;b.unknown=0;b.st=S_FREE;b.timer=0;b.vx=b.vy=0; b.x=std::lround(grass[k].point[0].x);b.y=std::lround(grass[k].point[0].y);
            }
            e.oldpos=pos(base.p[k]);e.oldvel=vel(base.p[k]);e.state=base.p[k].st;
            int lock=(e.state==S_FREE || e.state==S_RECALL)?0:base.p[k].timer;
            if(e.state==S_SLASH)lock+=cf.slash_post;
            if(e.state==S_KICK)lock+=cf.kick_post;
            if(e.state==S_THROW)lock+=cf.throw_post;
            e.freeAfter=lock-delay;
            e.armed=o.d[k].st==D_HAND && e.state!=S_THROW;
            if(e.oldvel.len()<20 && e.state==S_FREE){
                e.weight[0]=.40;e.weight[1]=.12;e.weight[2]=.24;e.weight[3]=e.weight[4]=.12;
            }else{
                e.weight[0]=.40;e.weight[1]=.14;e.weight[2]=.24;e.weight[3]=e.weight[4]=.11;
            }
        }
        inferTargets(o,delay);
        int models=n>4?3:10;
        for(int model=0;model<models;model++){
            Game g=base;
            double possibleShot[MAXP]{};
            for(int k=0;k<n;k++)if(k!=s && actor[k].valid && actor[k].hidden){
                V guess=grass[k].point[(model==2||model==6)?1:((model==4||model==5)?2:0)];
                g.p[k].x=std::lround(guess.x);g.p[k].y=std::lround(guess.y);
            }
            for(int h=-delay;h<=H;h++){
                if(duelEnemy>=0 && g.p[duelEnemy].alive && g.d[duelEnemy].st==D_HAND && g.p[duelEnemy].st==S_FREE)
                    armedMass[duelEnemy][h+delay]+=.1;
                if(h>=0)for(int k=0;k<n;k++)if(k!=s && actor[k].valid)actor[k].path[model][h]=pos(g.p[k]);
                if(h>=0)for(int k=0;k<n;k++)if(k!=s && actor[k].valid){
                    actor[k].modelHand[model][h]=(g.d[k].st==D_HAND && g.p[k].st!=S_THROW);
                    if(g.d[k].st==D_GROUND && (pos(g.d[k])-pos(g.p[k])).len()<cf.pick_r+250)actor[k].modelHand[model][h]=true;
                    if(model==0)actor[k].weapon[h]=actor[k].modelHand[model][h];
                }
                if(h==H)break;
                Action actions[MAXP]{};
                if(h<0){
                    actions[s]=histA[(t+h)%HISTORY];g.p[s]=history[(t+h)%HISTORY];
                    g.p[s].team=info().team[s];g.d[s]=histD[(t+h)%HISTORY];
                }
                else{
                    if(h==0){g.p[s]=o.me();g.p[s].team=info().team[s];g.d[s]=o.my_dart();}
                    g.p[s].unknown=1;
                }
                V selfPosition=h<0?pos(history[(t+h)%HISTORY]):me;
                for(int k=0;k<n;k++)if(k!=s && actor[k].valid){
                    V source=selfPosition;
                    if(n==4 && preferredEnemy[k]!=s && (model==2 || model==3 || model==6))
                        source=pos(g.p[preferredEnemy[k]]);
                    const auto &e=actor[k];V p=pos(g.p[k]), chase=(source-p).unit();
                    V dir=e.oldvel.unit()*clip(e.oldvel.len()/cf.run_v,0.,1.);
                    if(model==1)dir={};
                    if(model==2 || (e.state!=S_FREE && dir.len()==0))dir=chase;
                    if(model==3||model==4)dir=h>=3?chase.side()*(model==3?1:-1):(dir+chase*.45).unit();
                    if(model==5)dir=avgMove[k]*(1./cf.run_v);
                    if(model==6){
                        if(g.d[k].st==D_GROUND)dir=(pos(g.d[k])-p).unit();
                        else if((source-p).len()>5000)dir=(home-p).unit();
                        else if(g.d[k].st!=D_HAND)dir=chase*(-1.);
                        else dir=(chase+e.oldvel.unit()).unit();
                    }
                    if(model>=7){
                        V desired=(home-p).unit();
                        V toward=pos(g.d[k])-p;
                        double range=(source-p).len();
                        if(g.d[k].st==D_GROUND || g.d[k].st==D_BACK || g.d[k].st==D_CALL)
                            desired=toward.unit();
                        else if(range<6100){
                            if(model==7)desired=e.oldvel.unit();
                            if(model==8)desired=(chase.side()*(e.oldvel.dot(chase.side())>=0?1:-1)-chase*.45).unit();
                            if(model==9)desired=(chase+e.oldvel.unit()*.55).unit();
                        }
                        dir=desired;
                    }
                    if(e.hidden && (h<1 || cell(p+dir*cf.run_v,h)!=C_GRASS))dir={};
                    V next=p+dir*cf.run_v;
                    if(cell(next,h)==C_PIT){
                        V a=dir.side(),b=a*(-1);
                        if(chase.dot(a)<0)std::swap(a,b);
                        if(cell(p+a*cf.run_v,h)!=C_PIT)dir=a;
                        else if(cell(p+b*cf.run_v,h)!=C_PIT)dir=b;
                        else dir={};
                    }
                    actions[k]=command(dir);
                    if(g.p[k].st==S_RECALL)actions[k]={};
                    if(model==6 && g.d[k].st==D_HAND && g.p[k].st==S_FREE && !g.p[k].cd && (source-p).len()>2300 && (source-p).len()<4150 && h<1)
                        actions[k]=command({},A_DASH,chase);
                    if(model==6 && g.d[k].st==D_HAND && g.p[k].st==S_DASH && (source-p).len()<2100)
                        actions[k]=command({},A_MELEE,chase);
                    if(model>=7 && !e.hidden){
                        auto &victim=g.p[k];
                        int ix=std::max<int>(0,std::min(t,t+h-delay))%HISTORY;
                        V seen=pos(history[ix]),seenVel=vel(history[ix]);
                        V aim=(seen+seenVel*(model==7?1.:5.)-p).unit();
                        double range=(seen-p).len();
                        if(g.dash_moving(victim) && range<2150)actions[k]=command({},A_MELEE,aim);
                        if(victim.st==S_FREE){
                            bool held=g.d[k].st==D_HAND;
                            if(range<1550 && model!=8)actions[k]=command({},A_MELEE,aim);
                            else if(model!=8 && held && range<(model==7?3900:4800))
                                actions[k]=command(dir,A_THROW,aim);
                            else if(model==9 && !victim.cd && ((!held && range<4200) ||
                                (g.d[k].st==D_GROUND && (pos(g.d[k])-p).len()>1900 && (pos(g.d[k])-p).len()<3900)))
                                actions[k]=command({},A_DASH,dir);
                            else if(model==7 && g.d[k].st==D_GROUND && (pos(g.d[k])-p).len()>2600 && range>4600)
                                actions[k]=command({},A_RECALL);
                        }
                    }
                }
                if(duelEnemy>=0 && (model==7 || model==9)){
                    int k=duelEnemy;
                    if(o.p[k].vis && actor[k].valid){
                        int ix=std::max(0,std::min(t,t+h-delay))%HISTORY;
                        auto &seen=history[ix];auto &d=histD[ix];
                        bool hide=cell(pos(seen),h-delay)==C_GRASS && !seen.expose && (pos(seen)-pos(g.p[k])).len()>cf.see_r && d.st==D_HAND;
                        if(!hide){
                            Action a=simulatedReply(g,k,h,seen,d,model==7?0:4);
                            if(h<=1 && a.act==A_THROW && (g.p[k].st==S_FREE || g.p[k].st==S_RECALL)){
                                auto p=estimateReply(g.p[k],g.d[k],seen,d,h);
                                possibleShot[k]=clip(.18+p.p[A_THROW]*1.05,.18,.92);
                            }
                            actions[k]=a;
                        }
                    }
                }
                Dart before[MAXP];std::copy(g.d,g.d+n,before);
                g.over=false;g.step(actions);
                if(h<0)restoreContact(g,t+h+1);
                if(model<5 && h>=0)for(int k=0;k<n;k++)if(k!=s && (actor[k].valid||dart_flying(before[k].st))){
                    if((model==0 || before[k].st==D_BACK || before[k].st==D_CALL) && (dart_flying(before[k].st)||(before[k].st==D_RISE && g.d[k].st==D_CALL))){
                        flights[h+1].push_back({pos(before[k]),pos(g.d[k]),k,model});
                    }
                }
                if(duelEnemy>=0 && h>=0 && (model==7 || model==9)){
                    int k=duelEnemy;
                    if(possibleShot[k]>0 && before[k].st==D_OUT)
                        flights[h+1].push_back({pos(before[k]),pos(g.d[k]),k,model,possibleShot[k]*1.15});
                }
                for(int k=0;k<n;k++)if(k!=s && actor[k].valid && !g.p[k].alive){
                    auto &p=g.p[k];
                    if(p.cause==K_FALL){p.x=p.px;p.y=p.py;p.vx=p.vy=0;}
                    p.alive=1;p.st=S_FREE;p.timer=0;g.d[k]=before[k];
                }
            }
        }
        for(int k=0;k<n;k++)if(k!=s && actor[k].valid){
            auto &e=actor[k];
            e.armed=e.weapon[0]||e.weapon[3];
            if(models<10)for(int m=models;m<10;m++)std::copy(e.path[0],e.path[0]+H+1,e.path[m]);
            matchMotion(o,k,t-delay,delay);
            bool learned=forecastDuel(o,k,t-delay,delay);
            int cat=e.state!=S_FREE?3:(!e.armed?2:(e.oldvel.len()<50?1:0));
            auto &f=pastForecast[k][(t+4)%HISTORY];
            f.category=e.hidden?-1:cat; f.at=t+4;
            double sum=0;
            for(int m=0;m<NMODEL;m++){
                f.value[m]=e.path[m][4];
                double mix=trajectoryWeight[k];
                double prior=m>=10?mix*.46:(m>=7?0.12:m==5?.24:m==6?.12:e.weight[m])*(1.-mix);
                if(o.d[k].st==D_GROUND && m==6 && e.oldvel.len()>65 &&
                   (pos(o.d[k])-e.oldpos).unit().dot(e.oldvel.unit())>.80)prior*=3.4;
                if(stillTime[k]>=5 && !e.armed && (m==0||m==1||m==5))prior*=2.4;
                if(m>=13)prior=learned?1.5*(m==13?.6:.2):0.;
                e.weight[m]=prior*std::exp(3.2*skill[k][cat][m]);sum+=e.weight[m];
            }
            for(double &w:e.weight)w/=sum;
            for(int h=0;h<=H;h++){
                double armed=0;
                for(int m=0;m<NMODEL;m++)if(e.modelHand[m<models?m:0][h])armed+=e.weight[m];
                e.weapon[h]=armed>.31;
            }
            e.armed=e.weapon[0]||e.weapon[3];
            if(duelEnemy>=0 && contactFrame>t-delay && contact==EnemyParry){
                e.freeAfter=std::max(e.freeAfter,int(cf.slash_post)-(t-contactFrame));
                e.state=S_SLASHED;
            }
            if(e.enemy){
                double d=(e.path[0][0]-me).len()+(e.hidden?800:0);
                if(d<near){near=d;target=k;}
            }
        }
        crowdActivity=0;
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy)
            crowdActivity+=std::min(2,enemyShotCount[k]);
        crowdActivity=aliveEnemies>=2?clip(.20+crowdActivity/std::max(1,aliveEnemies)-.0015*t,0,1.):0.;
        for(int k=0;k<n;k++){
            rival[k]=-1;nearestOther[k]=30000;
            if(!actor[k].valid)continue;
            for(int j=0;j<n;j++)if(j!=k && j!=s && actor[j].valid && info().team[k]!=info().team[j]){
                double d=(actor[k].path[0][0]-actor[j].path[0][0]).len();
                if(actor[j].hidden && d>cf.see_r)d+=2300;
                if(d<nearestOther[k]){nearestOther[k]=d;rival[k]=j;}
            }
        }
    }
    // A visible dash can already be several movement steps ahead of the observation.
    // Enumerate the endpoints at which it can turn into a slash or kick.
    void knownDash(const Player &p,int k){
        if(p.st!=S_DASH)return;
        Body b{p.x,p.y,p.vx,p.vy}; V axis{p.ax*.001,p.ay*.001};
        for(int f=0;f<p.timer;f++){
            int timer=p.timer-f;
            bool moving=timer>cf.dash_post && timer<=cf.dash_t+cf.dash_post;
            if(moving){
                Body stop=b;
                bool ok=true;
                int h=f+cf.slash_pre-std::min<i64>(t,cf.delay);
                for(int i=0;i<cf.slash_pre;i++){
                    move(stop,{});if(cell(pos(stop),h-cf.slash_pre+i)==C_PIT)ok=false;
                }
                if(ok && h>0 && h<=9)lunges[h].push_back({pos(stop),1.8,!actor[k].weapon[h],k});
            }
            move(b,moving?axis*cf.dash_v:V{},moving);
            if(timer==cf.dash_post+1){b.vx=rdiv(b.vx*cf.run_v,cf.dash_v);b.vy=rdiv(b.vy*cf.run_v,cf.dash_v);}
        }
    }
    struct Shadow {V a,b;double w;};
    std::vector<Shadow> shadows[H+1];
    struct Lunge {V center;double weight; bool kick;int k;};
    std::vector<Lunge> lunges[H+1];
    // A throw or dash begun since our last visible frame has no observed dart
    // yet. Estimate the attacker's aim from the frame they could actually see.
    void speculate(const Obs &o){
        for(auto &v:lunges)v.clear();
        for(auto &v:shadows)v.clear();
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy){
            auto &e=actor[k];
            knownDash(o.p[k],k);
            double range=(e.path[0][0]-me).len();
            if(range>cf.range+1600)continue;
            if(e.hidden && t-lastSeen[k]>20){
                if(!e.armed)continue;
                for(V origin:grass[k].point){
                    if((origin-me).len()>6600)continue;
                    for(int r=-int(cf.delay);r<=0;r+=2){
                        int ix=std::max<int>(0,t+r-cf.delay)%HISTORY;
                        const auto &viewer=history[ix];
                        auto ds=histD[ix].st;
                        bool hidden=cell(pos(viewer),r-cf.delay)==C_GRASS && !viewer.expose && !dart_flying(ds) && ds!=D_RISE && (pos(viewer)-origin).len()>cf.see_r;
                        if(hidden)continue;
                        for(double lead:{2.,7.}){
                            V ray=(pos(viewer)+vel(viewer)*lead-origin).unit(),a=origin;
                            for(int age=0;age<8;age++){
                                int h=r+cf.throw_pre+age+1;
                                V b=a+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-age*cf.dart_dec);
                                if(!los(a,b))break;
                                if(h>0 && h<=9)shadows[h].push_back({a,b,0.12});
                                a=b;
                            }
                        }
                    }
                }
                continue;
            }
            for(int r=-int(cf.delay);r<=(duelEnemy>=0?6:2);r+=2){
                if(r<e.freeAfter)continue;
                int ix=std::min(t,std::max(0,t+r-int(cf.delay)));
                const Player &seen=history[ix%HISTORY];
                bool concealed=cell(pos(seen),ix-t)==C_GRASS && !seen.expose && !dart_flying(histD[ix%HISTORY].st) && histD[ix%HISTORY].st!=D_RISE && (e.oldpos-pos(seen)).len()>cf.see_r;
                if(concealed)continue;
                V origin=r>=0?e.path[0][r]:e.oldpos+(e.path[0][0]-e.oldpos)*clip(1.+double(r)/std::max<i64>(1,cf.delay),0,1);
                if(range<6100 && o.p[k].cd<=r+cf.delay && r<=1){
                    for(double lead:{1.,6.}){
                        V expected=pos(seen)+vel(seen)*lead;
                        V axis=(expected-origin).unit();
                        for(int travel=1;travel<cf.dash_t;travel++){
                            int h=r+cf.dash_pre+travel+cf.slash_pre;
                            if(h<1||h>9)continue;
                            V end=origin+axis*(cf.dash_v*travel+cf.dash_v-cf.acc+std::max<i64>(0,cf.dash_v-2*cf.acc));
                            double strike=(end-expected).len();
                            if(strike>cf.slash_reach+550 || cell(end,h)==C_PIT || !los(origin,end))continue;
                            double w=(enemyDashes[k]+1.)/(enemyDashes[k]+enemyShotCount[k]+2.);
                            lunges[h].push_back({end,w,!e.weapon[h],k});
                        }
                    }
                }
                double pickupReady=duelEnemy>=0?armedMass[k][r+cf.delay]:0.;
                bool suspected=duelEnemy>=0 && o.d[k].st!=D_HAND && pickupReady>.06;
                if(!suspected && (!e.armed || !e.weapon[std::max(0,r)]))continue;
                double likelihood=1.;
                if(cf.mode==1 && aliveEnemies>=2)likelihood=(1.-0.4)+0.4*clip(shotEvidence[k][s]*5.,.10,3.7);
                if(duelEnemy>=0 && !e.hidden){
                    Player projected=o.p[k];projected.x=std::lround(origin.x);projected.y=std::lround(origin.y);
                    projected.st=S_FREE;projected.timer=0;
                    Dart ready;ready.st=D_HAND;
                    auto reply=estimateReply(projected,ready,seen,histD[ix%HISTORY],r);
                    likelihood=clip(.23+8.*reply.p[A_THROW],.23,3.5);
                }
                for(int bucket=0;bucket<5;bucket++){
                    double lead=3.25*bucket;
                    V predicted=pos(seen)+vel(seen)*lead;
                    if(seen.st==S_DASH){
                        int ticks=std::max<i64>(0,std::min<i64>(cf.dash_t,seen.timer-cf.dash_post));
                        predicted=pos(seen)+V{seen.ax*.001,seen.ay*.001}*(cf.dash_v*std::min<double>(ticks,lead));
                    }
                    V aim=(predicted-origin).unit(),a=origin;
                    double left=cf.range;
                    for(int age=0;age<15 && left>0;age++){
                        int h=r+cf.throw_pre+age+1;if(h>9)break;
                        double dl=std::min(left,std::max<double>(cf.dart_vmin,cf.dart_v-age*cf.dart_dec));
                        V b=a+aim*dl; left-=dl;
                        if(!los(a,b))break;
                        if(h>0){
                            double w=(.18+leadFit[k][bucket]*.21)*(h<=r+cf.delay+3?1.:.38);
                            w*=likelihood;
                            if(suspected)w*=2.2*(.42+.58*pickupReady);
                            if(aliveEnemies>=2)w*=.25+.9*attention[k][s];
                            shadows[h].push_back({a,b,w});
                        }
                        a=b;
                    }
                }
            }
        }
    }
    // Reconsider the strategic destination less frequently than the tactical
    // controls. Grass exposure, escape space, and future waves change its value.
    // Exposure when approaching a fight from the side. An opponent whose
    // nearest rival is close can still turn on us if we cross its firing line.
    double flankScore(V p,int k) const{
        const auto &e=actor[k];V origin=e.path[0][0],delta=p-origin;
        double range=delta.len();
        if(range>8900 || range<2500 || rival[k]<0)return 0;
        V other=actor[rival[k]].path[0][0]-origin;
        if(nearestOther[k]>5900 || !los(origin,origin+other) || !los(p,origin))return 0;
        double separation=delta.unit().dot(other.unit());
        double angle=clip((.78-separation)/.64,0,1.);
        double engagement=clip((6400.-nearestOther[k])/2800.,0,1.);
        double distance=clip(1.-std::abs(range-4900)/3000.,0,1.);
        return angle*engagement*distance;
    }
    double exposureToCrowd(V p,int h,const Obs &o,bool opening=false) const{
        double first=0,second=0,crossfire=0;
        V axis[MAXP];double risk[MAXP]{};
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy){
            const auto &e=actor[k];V from=e.path[0][h],delta=p-from;
            double distance=delta.len();
            if(distance>9700)continue;
            bool concealed=cell(p,h)==C_GRASS && o.me().expose<=h && !opening &&
                      !dart_flying(o.my_dart().st) && o.my_dart().st!=D_RISE && distance>cf.see_r+300;
            axis[k]=delta.unit();
            double visibility=concealed?.10:los(p,from)?1.:.22;
            double alternate=nearestOther[k];
            double available=clip((alternate+1600-distance)/3200.,.10,1.);
            risk[k]=visibility*(e.weapon[h]?1.:.48)*available*clip((8700-distance)/4000.,0,1.4);
            if(risk[k]>first){second=first;first=risk[k];}else second=std::max(second,risk[k]);
            for(int u=0;u<k;u++)if(risk[u]>0)
                crossfire=std::max(crossfire,std::min(risk[k],risk[u])*(1.-axis[k].dot(axis[u]))*.5);
        }
        return first+1.3*second+crossfire;
    }
    bool seekPickup=false;
    V pickupPoint;
    int pickupGoal=-1;
    // A dart in a pit or jammed against a wall may still be picked up from
    // an adjacent cell. Compare the route to that cell with channeling.
    void pickPlan(const Obs &o,const std::vector<int> &dist){
        seekPickup=false;pickupGoal=-1;
        if(o.my_dart().st!=D_GROUND)return;
        V drop=pos(o.my_dart());double best=1e10;
        for(int j=0;j<(int)dist.size();j++)if(dist[j]>=0 && border[j]){
            V p{double(cell_center(j%live.nx)),double(cell_center(j/live.nx))};
            if((p-drop).len()>cf.pick_r+180 || circle_hits_wall(live,cf.body_r,p.x,p.y))continue;
            double time=dist[j]*(CELL*.1/cf.run_v);
            for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy && actor[k].weapon[std::min<int>(H,std::lround(time))]){
                V enemy=actor[k].path[0][std::min<int>(H,std::lround(time))];
                if(los(p,enemy))time+=clip((4500.-(p-enemy).len())/1300.,0.,2.5)*4.;
            }
            if(time<best){best=time;pickupGoal=j;pickupPoint=p;}
        }
        double channel=cf.recall_pre+4.+(drop-me).len()/cf.recall_v;
        seekPickup=pickupGoal>=0 && best<channel+4;
    }
    double channelSite(V p,int after) const{
        double risk=0;
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy){
            const auto &e=actor[k];V q=e.path[0][std::min(after,H)];
            double d=(p-q).len();bool clear=los(p,q);
            double danger=clear?clip((7300-d)/2500.,0.,1.9):0.;
            if(!e.weapon[std::min(after+8,H)])danger*=.40;
            risk=std::max(risk,danger+clip((3900-d)/1800.,0,1.5)*(clear?.8:.35));
        }
        return risk;
    }
    double sidestepRoom(V p,V side,int h)const{
        double usable[2]{};
        for(int k=0;k<2;k++){
            V dir=side*(k?1.:-1.);
            for(int a=1;a<=4;a++){
                V next=p+dir*(a*400);
                if(cell(next,h+2*a)==C_PIT || circle_hits_wall(live,cf.body_r,std::lround(next.x),std::lround(next.y)))break;
                usable[k]+=400;
            }
        }
        return (.65*std::max(usable[0],usable[1])+.35*std::min(usable[0],usable[1]))/1600.;
    }
    V recoveryGoal{};
    bool recoveryRoute=false,planCall=false;
    int lostSince=-1;
    // Price the full unarmed interval, including the time between a completed
    // channel and the catch. A wall can shield the channel while allowing the
    // returning weapon to pass. The enemy can still parry that return.
    double callExpense(V point,V drop,int travel)const{
        V displacement=point-drop;
        Dart returning;returning.st=D_CALL;returning.age=0;
        double remaining=displacement.len()-cf.catch_r;
        int flight=0;while(remaining>0 && flight<36){
            remaining-=dart_step_len(cf,returning);returning.age++;flight++;
        }
        double cost=cf.recall_pre+flight;
        if(cell(point,travel+cf.recall_pre)==C_PIT)return cost+160;
        const auto &e=actor[target];
        V enemy=e.path[0][std::min(H,travel+4)];
        double dist=(enemy-point).len();
        bool clear=los(point,enemy);
        double melee=std::max(0.,(dist-reach)/cf.run_v);
        if(memory[target].cd<cf.delay+travel+5 && clear && dist<5900)
            melee=std::min(melee,cf.dash_pre+2.+std::max(0.,(dist-4000)/cf.run_v));
        double threat=clip((14.-melee)/9.,0.,1.)*(clear?1.:.35);
        double firing=cf.throw_pre+std::max(0.,(dist-radius)/(.80*cf.dart_v));
        double lock=std::max(0,e.freeAfter-travel);
        if(e.weapon[std::min(H,travel+7)] && clear){
            threat+=clip((cf.recall_pre+2.-firing-lock)/8.,0.,1.25);
            if(dist<5500)threat+=.22;
        }
        cost+=42*threat;
        V intercept=e.path[0][std::min<int>(H,travel+cf.recall_pre)];
        if(e.weapon[H] && swept(drop-intercept,point-intercept)<reach && los(drop,intercept))
            cost+=28*clip((4600.-(intercept-drop).len())/3300.,.2,1.);
        return cost;
    }
    int recoveryDestination(const Obs &o,const std::vector<int>& dist){
        recoveryRoute=false;
        if(duelEnemy<0 || target<0 || o.my_dart().st!=D_GROUND)return -1;
        V drop=pos(o.my_dart());double best=1e20;int dest=-1;
        auto consider=[&](V point,bool pickup){
            int id=index(point);if(id<0 || dist[id]<0 || cell(point)==C_PIT ||
                circle_hits_wall(live,cf.body_r,std::lround(point.x),std::lround(point.y)))return;
            double separation=(point-me).len();
            double travel=std::max(dist[id]*(CELL*.10/cf.run_v),separation/cf.run_v);
            if(separation<3800 && !o.me().cd && los(point,me)){
                double dash=cf.dash_pre+cf.dash_t+std::abs(separation-cf.dash_t*cf.dash_v)/cf.run_v+2.;
                if(pickup && separation>1950 && separation<3200)dash-=2.;
                travel=std::min(travel,dash);
            }
            if(!pickup && separation<650)travel=0;
            if(travel>best+8 || cell(point,int(travel)+3)==C_PIT)return;
            auto &e=actor[target];V q=e.path[0][std::min<int>(H,travel+2)];
            double proximity=(q-point).len(),cost=travel;
            if(pickup){
                if(e.weapon[std::min<int>(H,travel+2)] && los(point,q)){
                    double lock=clip((travel+3-e.freeAfter)/7.,0.,1.);
                    cost+=30*lock*clip((3750-proximity)/1850.,0.,1.75);
                }
                cost+=.0015*(point-drop).len();
            }else cost+=callExpense(point,drop,std::lround(travel));
            // A pickup inside an armed defender's reach costs extra once its swing recovers.
            if(pickup && e.armed && travel+2>e.freeAfter && los(point,q)){
                double control=clip((3250-proximity)/1400.,0.,1.5);
                double ready=clip((travel+2-e.freeAfter)/6.,0.,1.);
                cost+=32*control*ready;
            }
            if(cost>=best)return;
            best=cost;dest=id;recoveryGoal=point;planCall=!pickup;
        };
        consider(me,false);
        for(int j=0;j<int(dist.size());j++)if(dist[j]>=0 && border[j]){
            V p{double(cell_center(j%live.nx)),double(cell_center(j/live.nx))};
            if((p-me).len()<6400)consider(p,false);
        }
        consider(drop,true);
        for(double fraction:{.65,.94})for(V dir:dirs)consider(drop+dir*(fraction*cf.pick_r),true);
        if(dest>=0){
            recoveryRoute=true;seekPickup=!planCall;pickupPoint=recoveryGoal;
        }
        return dest;
    }
    int postLease=-1,quietPressure=0,openOffers=0,backSteps=0,lastOffer=-99;
    double claim=0,opening=0,routeClaim=0;
    int ownedSteps=0,controlTicks=0,contestUntil=-1;
    double startLead[MAXP]{};bool initialRefuge[MAXP]{};
    bool occupied=false,haveSight[MAXP]{},firstHold[MAXP]{}; V initialPost[MAXP]{};
    bool readGuard(const Obs &o,int holder,int oldFrame,V then){
        const auto &opp=o.p[holder];
        if(enemyShotCount[holder])return false;
        V start{double(info().spx[holder]),double(info().spy[holder])};
        V q=pos(opp);
        double spread=0;
        for(int j=0;j<=std::min(oldFrame,9);j++){
            const auto &step=trail[holder][(oldFrame-j)%TRAIL];
            if(step.frame!=oldFrame-j || step.state!=S_FREE || step.dart!=D_HAND)continue;
            spread=std::max(spread,(step.p-q).len());
        }
        double outer=0,top=0;int active=0;
        for(int age=0;age<=std::min(oldFrame-1,18);age++){
            const auto &z=trail[holder][(oldFrame-age)%TRAIL];
            if(z.frame!=oldFrame-age)continue;
            outer=std::max(outer,(z.p-start).len());
            if(z.state==S_FREE && z.dart==D_HAND){
                active++;top=std::max(top,z.v.len());
            }
        }
        bool anchored=opp.vis && ((active>=3 && top<cf.run_v*.78 && outer<1100) ||
            (active>=14 && outer<620 && spread<770));
        double range=(q-then).len();
        bool inRange=range<6200 && range>2500 && opp.vis && los(q,then) && opp.st==S_FREE &&
            o.d[holder].st==D_HAND && (cell(then)!=C_GRASS || history[oldFrame%HISTORY].expose ||
            range<cf.see_r);
        if(oldFrame>0 && inRange)quietPressure=std::min(160,quietPressure+1);
        else if(oldFrame>0 && !opp.vis)quietPressure=std::max(0,quietPressure-1);
        // Count shots the defender could have made. Rewind to a free
        // frame, aim at the observations then available, and trace the
        // moving dart against our actual subsequent path.
        int fired=oldFrame-10;
        if(fired>=int(cf.delay) && fired>=lastOffer+4){
            const auto &v=trail[holder][fired%TRAIL];
            const auto &seen=history[(fired-cf.delay)%HISTORY];
            if(v.frame==fired && v.state==S_FREE && v.dart==D_HAND &&
               (pos(seen)-v.p).len()<5500 && (cell(pos(seen))!=C_GRASS || seen.expose ||
               (pos(seen)-v.p).len()<cf.see_r)){
                bool clear=false;
                for(double lead:{0.,5.,10.}){
                    V origin=v.p+v.v*.7,ray=(pos(seen)+vel(seen)*lead-origin).unit(),p=origin;
                    for(int j=cf.throw_pre+1;j<=9;j++){
                        V end=p+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(j-cf.throw_pre-1)*cf.dart_dec);
                        if(!los(p,end))break;
                        if(swept(p-pos(history[(fired+j-1)%HISTORY]),end-pos(history[(fired+j)%HISTORY]))<radius-130){
                            clear=true;break;
                        }
                        p=end;
                    }
                    if(clear)break;
                }
                if(clear){openOffers++;lastOffer=fired;}
            }
        }
        V toUs=(then-q).unit();
        if(inRange && vel(opp).dot(toUs)<-.35*cf.run_v && (q-home).len()<3200)
            backSteps=std::min(200,backSteps+1);
        bool reluctant=oldFrame>=40 && quietPressure>=8 && openOffers>=24 &&
            (backSteps>=7 || oldFrame>=235);
        bool recovering=oldFrame>=12 && o.d[holder].st==D_HAND &&
            (opp.st==S_SLASHED || (contact==EnemyParry && t-contactFrame<=10));
        return (anchored || reluctant || recovering) && o.d[holder].st==D_HAND;
    }
    // Route distance accounts for bridges. Radius from the stable area's
    // centroid also distinguishes the two sides of a large permanent island.
    void readTerritory(const Obs &o){
        claim=opening=routeClaim=0;occupied=false;
        auto &map=info().M();
        if(cf.mode>1 || !map.nwave || t>=wave_fall_step(cf,map.nwave-1))return;
        int us=index(me);if(us<0 || refuge[us]<0)return;
        double ours=refuge[us]*CELL*.1+(me-home).len()*.43;
        double theirs=1e20;int holder=-1;
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy){
            V q=actor[k].oldpos;int tile=index(q);
            if(tile<0 || refuge[tile]<0)continue;
            double d=refuge[tile]*CELL*.1+(q-home).len()*.43;
            if(d<theirs){holder=k;theirs=d;}
        }
        if(t==0)for(int k=0;k<n;k++)if(k!=s){
            V start{double(info().spx[k]),double(info().spy[k])};
            int at=index(start);
            if(at>=0 && refuge[at]>=0){
                startLead[k]=ours-(refuge[at]*CELL*.1+(start-home).len()*.43);
                initialRefuge[k]=refuge[at]<=25 && (start-home).len()<2900;
            }
        }
        if(holder<0)return;
        if(t==0 && duelEnemy==holder && !o.p[holder].vis && initialRefuge[holder] && startLead[holder]>2100){
            // The opening positions are public even when the occupant is
            // concealed. Allow a route change; attacks still require sight.
            V start{double(info().spx[holder]),double(info().spy[holder])};
            int tile=index(start);
            if(tile>=0 && refuge[tile]>=0 && refuge[tile]<=20 &&
               (start-home).len()<2400 && ours>3300)
                postLease=t+42;
        }
        bool held=o.my_dart().st==D_HAND;
        double gap=ours-theirs;
        if(gap>650 && theirs<2300)ownedSteps=std::min(42,ownedSteps+2);
        else ownedSteps=std::max(0,ownedSteps-1);
        claim=clip((gap-380)/1400.,0.,1.)*clip((2800-theirs)/1200.,0.,1.);
        if(ownedSteps>9)claim=std::max(claim,.68*clip((ours-550)/1100.,0.,1.));
        // An entrant and a holder have different options even when they are
        // equally far from each other. Compare simultaneous observations.
        const auto &opp=o.p[holder];int at=index(actor[holder].oldpos);
        int oldFrame=std::max<int>(0,t-cf.delay);
        V then=pos(history[oldFrame%HISTORY]);int earlier=index(then);
        double oldDistance=earlier>=0 && refuge[earlier]>=0?refuge[earlier]*CELL*.1+(then-home).len()*.43:ours;
        double edge=oldDistance-theirs;
        bool holding=opp.vis && at>=0 && refuge[at]>=0 && refuge[at]<=18 &&
            (theirs<1450 || live.w[at]<0) && edge>1750 && o.d[holder].st==D_HAND;
        if(holding && t>=cf.delay)controlTicks=std::min(120,controlTicks+1);
        else if(!holding)controlTicks=std::max(0,controlTicks-2);
        // Infer residence from observed terrain and displacement. A rival
        // running through the core on its way to us is still an attacker.
        if(opp.vis){
            V q=pos(opp);double deep=(q-home).len();
            if(!haveSight[holder]){
                haveSight[holder]=true;firstHold[holder]=holding && initialRefuge[holder] && startLead[holder]>1950 && edge>2200 && deep<2400;
                initialPost[holder]=q;
            }
            bool samePost=(q-initialPost[holder]).len()<2400;
            if(!samePost || !holding)firstHold[holder]=false;
            bool forced=false;
            if(controlTicks>=36 && live.w[us]>=0 && refuge[us]>30 && live.w[at]<0){
                V route=(home-me).unit(),front=me+route*std::min(3800.,(home-me).len());
                V foe=pos(opp),toward=foe-me;double along=toward.dot(route);
                bool blocksWay=along>0 && (foe-front).len()<2900 && std::abs(toward.dot(route.side()))<2100;
                // A straight approach across holes or flush against a wall is
                // a poor way to dislodge a ready defender.
                bool runway=true;int ahead=std::min(8,int((front-me).len()/420.));
                for(int h=1;h<=ahead;h++){
                    int id=index(me+route*(h*420.));
                    if(id<0 || border[id]<2 || jumpLatest[id]<t+h+22){runway=false;break;}
                }
                int deadline=std::min<int>(walkLatest[us],wave_fall_step(cf,live.w[us]))-t;
                forced=runway && blocksWay && deadline<78;
            }
            if(oldFrame>=1 && (firstHold[holder] || forced) &&
               holding && !enemyShotCount[holder] && duelEnemy>=0){
                postLease=t+150;
            }
        }
        bool disposition=n!=2 || readGuard(o,holder,oldFrame,then);
        if(disposition)contestUntil=postLease;
        else if(n==2){contestUntil=-1;anchorUntil=-1;assaultUntil=-1;}
        occupied=duelEnemy>=0 && t<=contestUntil && !enemyShotCount[holder];
        if(!occupied || !held)claim=0;
        if(!occupied)ownedSteps=0;
        double engagement=(me-actor[holder].oldpos).len();
        // Keep a wide approach while the defender has throwing initiative.
        // The attack planner still knows the territorial deficit.
        double movement=opp.vis?vel(opp).len()/std::max<i64>(1,cf.run_v):0.;
        double spacing=clip((engagement-6000)/2400.,0.,1.);
        double mobile=clip((movement-.60)/.40,0.,1.);
        routeClaim=claim*(0.12+(1.-0.12)*std::max(spacing,0.68*mobile));
        double clearSpace=clip((engagement-(cf.dash_v*cf.dash_t+reach+2800))/2500.,0.,1.);
        bool measuredApproach=!initialRefuge[holder] && opp.vis && !enemyDashes[holder] &&
            (slowEvidence>=t || confirmedUntil>=t || patientSteps>1.5);
        bool advantage=initialRefuge[holder] && startLead[holder]>1200;
        bool advance=n!=2 || (advantage?disposition:(!enemyDashes[holder] || measuredApproach));
        opening=advance && held && t<45 && aliveEnemies==1 && !enemyShotCount[holder]?clearSpace*
            clip((ours-1600)/2500.,0.,1.)*clip((45.-t)/40.,0.,1.):0.;

    }
    void navigate(const Obs &o){
        bool ground=o.my_dart().st==D_GROUND;
        bool newDrop=ground && (t==0 || histD[(t-1)%HISTORY].st!=D_GROUND);
        if(duelEnemy>=0 && ground){if(lostSince<0)lostSince=t;}
        else if(o.my_dart().st==D_HAND){lostSince=-1;recoveryRoute=false;}
        if(!nav.empty() && t%(ground && duelEnemy>=0?4:9)!=0 && !newDrop)return;
        int w=live.nx,start=index(me);
        if(start<0 || !border[start]){
            double bestDist=1e20;
            for(int j=0;j<(int)border.size();j++)if(border[j]){
                V p{double(cell_center(j%w)),double(cell_center(j/w))};double d=(p-me).len();
                if(d<bestDist){start=j;bestDist=d;}
            }
        }
        auto dist=routeFrom(start);pickPlan(o,dist);
        if(duelEnemy>=0 && ground){
            int next=recoveryDestination(o,dist);
            if(next>=0){goal=recoveryGoal;nav=routeFrom(next);return;}
        }
        double best=-1e30;int idx=-1;
        for(int j=0;j<(int)dist.size();j++){
            if(dist[j]<0 || border[j]==0)continue;
            V p{double(cell_center(j%w)),double(cell_center(j/w))};
            double central=(p-home).len();
            double urgency=clip((t+75.)/200.,.50,1.);
            double val=-.28*central+.28*std::min(border[j],4)*CELL+permanent[j]*(aliveEnemies>=2?85+10*crowdActivity:95)*urgency;
            int fall=wave_fall_step(cf,live.w[j]);
            if(fall>=0)val-=clip(145-(fall-t),0,160)*47;
            if(target>=0 && aliveEnemies==1 && t>cf.col_start-130 && live.w[j]>=0){
                int theirs=index(actor[target].path[0][0]);
                if(theirs>=0 && live.w[theirs]<0)val-=std::min(1800.,(t-cf.col_start+130)*24.);
            }
            if(aliveEnemies==1 && target>=0){
                int theirs=index(actor[target].oldpos);
                bool contested=theirs>=0 && live.w[theirs]<0;
                double pressure=clip((t-cf.col_start+190)/130.,.12,1.);
                if(live.w[j]>=0){
                    double time=wave_fall_step(cf,live.w[j])-t;
                    val-=2200*(contested?1.0:.58)*pressure*clip((360.-time)/215.,.25,1.);
                }
            }
            if(target>=0 && refuge[j]>=0 && o.my_dart().st==D_HAND){
                int enemyId=index(actor[target].oldpos);
                if(enemyId>=0 && refuge[enemyId]>=0){
                    double lead=clip((refuge[enemyId]+15)/95.,0,1.);
                    double deadline=clip((t-cf.col_start+150)/170.,.08,1.);
                    double exposure=clip((refuge[j]-(16+40*lead))/70.,0.,1.8);
                    val-=2400*exposure*(deadline+.37*(1.-lead));
                }
            }
            if(live.c[j]==C_GRASS && live.w[j]<0){
                double d=target<0?14000:(actor[target].oldpos-p).len();
                double safe=clip((d-2700)/3000.,.17,1.);
                val+=(2300+5500*clip((coverCount[j]-3.)/16.,0.,1.))*safe;
            }
            if(live.c[j]==C_GRASS)val+=aliveEnemies>=2?4050-950*crowdActivity:2100;
            val-=dist[j]*CELL*.025;
            if(target>=0){
                double d=(p-actor[target].path[0][0]).len();
                if(o.my_dart().st==D_GROUND && seekPickup)d=(p-pos(o.my_dart())).len(),val-=d*.85;
                else{
                    double ideal=aliveEnemies>=2?7800:(actor[target].armed?7200:4900);
                    val-=std::abs(d-ideal)*.53;
                    if(t>100){
                        V away=(p-actor[target].path[0][0]).unit();
                        if(cell(p+away*2700,40)==C_PIT)val-=420;
                    }
                    if(aliveEnemies>=2)for(int k=0;k<n;k++)if(actor[k].valid&&actor[k].enemy && k!=target)
                        val-=std::max(0.,4700-(p-actor[k].path[0][0]).len())*.8;
                }
            }
            if(aliveEnemies>=2){
                for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy){
                    const auto &e=actor[k];
                    double d=(p-e.path[0][0]).len();
                    bool cover=(live.c[j]==C_GRASS && o.me().expose<12 && d>cf.see_r+400);
                    double danger=std::max(0.,7100-d)*.60+clip(nearestOther[k]+500-d,0,3800)*.59;
                    bool shield=!los(p,e.path[0][0]) && !e.hidden;
                    if(shield)danger*=.45;
                    if(e.armed && !cover && los(p,e.oldpos))val-=clip((7700-d)/2500.,0.,1.)*1050*attention[k][s];
                    if(e.armed && !cover)val-=danger*(1+.32*crowdActivity)*1.4;
                    else val-=danger*.30;
                }
            }
            if(aliveEnemies>=2){
                val-=exposureToCrowd(p,6,o)*1088;
                double opp=0;
                for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy && nearestOther[k]<5200){
                    double d=(p-actor[k].path[0][0]).len();
                    if(d>3500 && d<7800 && los(p,actor[k].path[0][0]))
                        opp=std::max(opp,1350*(1-std::abs(d-5450)/3000));
                }
                double flank=0;
                for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy)
                    flank=std::max(flank,flankScore(p,k));
                val+=150*flank;
                val+=opp*(1.-.93*crowdActivity);
                if(live.w[j]>=0)val-=1900*clip((240.-(wave_fall_step(cf,live.w[j])-t))/120.,0.,1.);
            }
            if(ground){
                if(seekPickup)val-=1.35*(p-pickupPoint).len();
                else val-=2550*channelSite(p,6)+.16*(p-me).len();
            }else if(target>=0 && o.my_dart().st==D_HAND && o.d[target].st==D_GROUND){
                V mark=pos(o.d[target]),owner=actor[target].path[0][4];
                double contest=clip(((owner-mark).len()-1150)/2300.,0.,1.);
                double reachIt=clip((6300-(me-mark).len())/2500.,0.,1.);
                double cover=clip((5000-(p-mark).len())/2500.,0.,1.);
                double standoff=clip(((p-owner).len()-1700)/1300.,0.,1.);
                val+=1800*contest*reachIt*cover*standoff;
            }
            if(duelEnemy>=0 && target>=0 && !actor[target].hidden && actor[target].armed && o.my_dart().st==D_HAND){
                V enemy=actor[target].oldpos,delta=p-enemy;
                double range=delta.len();
                if(range<8100 && range>2400 && los(p,enemy) && (live.c[j]!=C_GRASS || range<cf.see_r)){
                    double room=sidestepRoom(p,delta.unit().side(),std::min(25,dist[j]/5));
                    double urgency=clip((range-2300)/1700.,0.,1.)*clip((8100-range)/2300.,0.,1.);
                    val-=2600*(1.-room)*urgency;
                }
            }
            if(duelEnemy>=0 && target>=0 && o.my_dart().st==D_HAND && narrowCore>0){
                const auto &e=actor[target];int theirs=index(e.oldpos);
                double reserve=live.w[j]<0?1.:refuge[j]<0?0.:clip(1.-refuge[j]/55.,0.,1.);
                double late=clip((t+55.)/160.,.35,1.);
                double advantage=theirs>=0 && live.w[theirs]>=0?1.:.52;
                V toward=(e.oldpos-p).unit();double backing=0;
                for(double side:{-.48,0.,.48}){
                    V away=(toward+toward.side()*side).unit()*(-1.);
                    int landing=cell(p+away*kickTravel,55);
                    backing+=landing==C_PIT?0.:1./3;
                }
                double robust=clip(permanent[j]/24.,0.,1.);
                val+=3600*narrowCore*late*(reserve*(.54+.46*robust)*advantage+.34*backing);
                if(live.w[j]<0 && theirs>=0 && live.w[theirs]>=0){
                    double distance=(p-e.oldpos).len();
                    val+=3600*.22*narrowCore*clip((distance-3250)/1800.,0.,1.);
                }
            }
            if(refuge[j]>=0 && (claim>0 || opening>0)){
                double weight=1.0*(routeClaim+0.15*opening);
                val-=weight*(.42*central+std::min(160,refuge[j])*30.);
                if(live.w[j]<0)val+=weight*(1080+32*permanent[j]);
            }
            if(val>best){best=val;idx=j;goal=p;}
        }
        if(idx>=0)nav=routeFrom(idx);
        else{nav.clear();goal=home;}
    }
    double navigation(V p) const{
        int j=index(p);
        double d=(p-goal).len();
        if(j>=0 && !nav.empty() && nav[j]>=0){
            V center{double(cell_center(j%live.nx)),double(cell_center(j/live.nx))};
            d=std::max(0.,nav[j]*CELL*.1+(p-center).dot((center-goal).unit()));
        }
        return -d;
    }
    // Terrain checked at each tick under the appropriate movement state.
    struct Body {i64 x,y,vx,vy;};
    void move(Body &b,V v,bool set=false) const{
        i64 dx=std::lround(v.x)-b.vx,dy=std::lround(v.y)-b.vy;
        if(!set)cap_len(dx,dy,cf.acc);
        b.vx+=dx;b.vy+=dy;
        move_body(live,cf.body_r,b.x,b.y,b.vx,b.vy);
    }
    struct Plan {Action a; double score=-1e20;};
    V stunEnd(const Player &p) const{
        Body b{p.x,p.y,p.vx,p.vy};
        for(int z=0;z<p.timer;z++){
            move_body(live,cf.body_r,b.x,b.y,b.vx,b.vy);
            b.vx=rdiv(b.vx*cf.kick_keep,1000);b.vy=rdiv(b.vy*cf.kick_keep,1000);
        }
        return pos(b);
    }
    // Score each attack policy against the next observation that actually
    // arrives, separately for an armed or empty-handed opponent.
    // Estimate when an empty hand can recover its weapon. For a flying
    // boomerang follow both legs from its actual age and remaining range.
    double recoveryTime(const Game &g,int k) const{
        const Player &p=g.p[k];Dart d=g.d[k];V owner=pos(p);
        if(d.st==D_HAND && p.st!=S_THROW)return 0;
        if(p.st==S_THROW && d.st==D_HAND)return 26;
        double gap=(pos(d)-owner).len();
        if(d.st==D_GROUND){
            double walk=std::max(0.,gap-cf.pick_r)/cf.run_v;
            if(!p.cd && gap>1950 && los(owner,pos(d)))walk=std::min(walk,cf.dash_pre+cf.dash_t+std::abs(gap-cf.dash_t*cf.dash_v)/cf.run_v);
            if(!los(owner,pos(d)) || cell((pos(d)+owner)*.5)==C_PIT)walk+=5;
            return std::min(walk,cf.recall_pre+gap/cf.recall_v+4.);
        }
        if(d.st==D_RISE)return p.timer+gap/cf.recall_v+4.;
        if(!dart_flying(d.st))return 30;
        V point=pos(d);
        int h=0;
        if(d.st==D_OUT){
            while(d.left>0 && h<27){
                int step=std::min<i64>(d.left,dart_step_len(cf,d));
                point=point+vel(d)*(.001*step);d.left-=step;d.age++;h++;
            }
            d.st=D_BACK;d.age=0;
        }
        double left=(point-owner).len()-cf.catch_r;
        while(left>0 && h<36){left-=dart_step_len(cf,d);h++;d.age++;}
        return h;
    }
    double weaponBalance(const Game &g) const{
        if(!g.p[s].alive)return 0;
        if(aliveEnemies>=2){
            double danger=0,opportunity=0,ours=recoveryTime(g,s);
            for(int k=0;k<n;k++)if(k!=s && g.p[k].alive && actor[k].enemy){
                double dist=(pos(g.p[s])-pos(g.p[k])).len();
                double contact=clip((9000-dist)/4800.,.08,1.);
                double margin=clip((recoveryTime(g,k)-ours)/12.,-1.4,1.4);
                danger=std::max(danger,-margin*contact*(.62+.38*attention[k][s]));
                opportunity=std::max(opportunity,margin*contact);
            }
            return .60*opportunity-1.15*danger;
        }
        if(!g.p[target].alive)return 0;
        double distance=(pos(g.p[s])-pos(g.p[target])).len();
        double urgency=clip((9500-distance)/5700.,.18,1.);
        double ours=recoveryTime(g,s),theirs=recoveryTime(g,target);
        double differential=clip((ours-theirs)/12.,-1.,1.);
        return -urgency*(differential+.35*(std::min(ours,24.)-std::min(theirs,24.))/24.);
    }
    enum Contact { NoContact, EnemyParry, DartClash };
    int contactFrame=-1,parries=0;
    Contact contact=NoContact;
    V stoppedDart{};
    void noticeContact(const Obs &o){
        if(duelEnemy<0 || !t)return;
        const Dart &before=histD[(t-1)%HISTORY],&after=o.my_dart();
        if(!dart_flying(before.st) || after.st!=D_GROUND)return;
        V a=pos(before),end=pos(after),v;
        double distance=dart_step_len(cf,before);
        if(before.st==D_OUT)v=vel(before)*(.001*std::min<double>(before.left,distance));
        else v=(me-a).unit()*std::min(distance,(me-a).len());
        i64 wx,wy;
        if((before.st!=D_CALL || !cf.recall_wall) && seg_wall(live,before.x,before.y,
            std::lround(a.x+v.x),std::lround(a.y+v.y),wx,wy) && (V{double(wx),double(wy)}-end).len()<4)return;
        contactFrame=t;stoppedDart=end;
        // A stationary dart at its turning point may also have clashed.
        contact=(end-a).len()<1 && distance>2?EnemyParry:DartClash;
        if(contact==EnemyParry)parries++;
    }
    void restoreContact(Game &g,int frame) const{
        if(duelEnemy<0 || frame!=contactFrame)return;
        int k=duelEnemy;auto &p=g.p[k];auto &d=g.d[k];V q=pos(p);
        if(contact==EnemyParry){
            V offset=q-stoppedDart;
            if(offset.len()>reach){
                V possible=stoppedDart+offset.unit()*(reach-40.);
                if(cell(possible,frame-t)!=C_PIT && !circle_hits_wall(live,cf.body_r,possible.x,possible.y)){
                    p.x=std::lround(possible.x);p.y=std::lround(possible.y);
                }
            }
            p.st=S_SLASHED;p.timer=cf.slash_post;p.vx=p.vy=0;
            d.st=D_HAND;d.x=p.x;d.y=p.y;
        }else if(contact==DartClash){
            V offset=pos(d)-stoppedDart;
            V drop=stoppedDart+offset.unit()*std::min<double>(offset.len(),cf.dart_r*1.75);
            d.x=std::lround(drop.x);d.y=std::lround(drop.y);d.left=d.age=d.vx=d.vy=0;
            d.st=(drop-q).len()<=cf.pick_r?D_HAND:D_GROUND;
            if(d.st==D_HAND){d.x=p.x;d.y=p.y;}
        }
    }
    struct Response {
        int frame=-1,category=0;
        Player next[5];
        double skill[2][5]{};
    };
    Response response[MAXP];
    void ratePolicies(const Obs &o,int k,int frame){
        auto &r=response[k];
        if(r.frame!=frame || !o.p[k].vis)return;
        const auto &actual=o.p[k];double quality[5],mean=0;
        for(int m=0;m<5;m++){
            const auto &p=r.next[m];double miss=(pos(p)-pos(actual)).len();
            quality[m]=1./(1.+miss*miss/(275.*275.));
            if(p.st!=actual.st)quality[m]*=.16;
            if(actual.st==S_THROW || actual.st==S_DASH){
                V da{(p.ax-actual.ax)*.001,(p.ay-actual.ay)*.001};
                quality[m]*=clip(1.-.52*da.len(),.05,1.);
            }
            mean+=quality[m]/5.;
        }
        for(int m=0;m<5;m++)
            r.skill[r.category][m]=.94*r.skill[r.category][m]+.06*(quality[m]-mean);
    }
