    static constexpr short releaseRoots[]={0,765,1464,2195,2842,};
    V compactShot(const Obs &o,V origin,double &quality) const{
        int frame=std::max<int>(0,t-cf.delay),age=0;
        while(age<=32 && age<=t && histD[(t-age)%HISTORY].st!=D_GROUND)age++;
        if(age>t)age=33;
        const auto &p=o.p[target],&past=history[frame%HISTORY];const auto &d=o.d[target];
        V v=pos(p),axis=(v-me).unit(),side=axis.side();double gap=(v-me).len();
        double sign=vel(p).dot(side);if(std::abs(sign)<45)sign=(home-v).dot(side);
        if(sign<0)side=side*(-1.);
        double f[54];int k=0;auto add=[&](double a){f[k++]=a;};
        auto vec=[&](V z){add(z.dot(axis));add(z.dot(side));};
        add(gap);add(p.st);add(p.timer);add(p.cd);add(d.st);add(d.left);add(past.st);add(histD[frame%HISTORY].st);
        add(std::min(age,32));add(t-frame);
        vec(vel(p));vec(vel(o.me()));vec(v-home);vec(me-pos(past));vec({double(p.ax),double(p.ay)});vec(pos(d)-v);
        vec(age<=32?pos(histD[(t-age)%HISTORY])-v:V{});
        for(int h:{2,5,10}){
            const auto &past=trail[target][std::max(0,frame-h)%TRAIL];
            vec(past.frame==std::max(0,frame-h)?(v-past.p)*(1./h):vel(p));
        }
        for(V ray:{axis,axis*(-1),side,side*(-1),(axis+side)*.707,(axis-side)*.707,(side-axis)*.707,(axis+side)*(-.707)})
          for(double len:{550.,1200.,2000.}){
            int cellType=cell(v+ray*len);add(cellType==C_PIT?1:cellType==C_WALL?2:0);
          }
        V samples[40];double weights[40];int count=0;double total=0;
        auto sample=[&](V targetPos,double w){
            V delta=targetPos-v;
            if(p.st!=S_DASH){
                Body z{p.x,p.y,0,0};
                int steps=std::max(1,int(std::ceil(delta.len()/200.)));
                for(int i=0;i<steps;i++){
                    Body next=z;move(next,delta*(1./steps),true);
                    if(cell(pos(next))==C_PIT)break;
                    z=next;
                }
                targetPos=pos(z);
            }
            samples[count]=targetPos;weights[count++]=w;total+=w;
        };
        for(int j:releaseRoots){
            while(releaseTree[j].f>=0){const auto &n=releaseTree[j];j=f[n.f]<=n.cut?n.l:n.r;}
            for(int q=0;q<5;q++){
                const auto &b=releaseLeaf[releaseTree[j].l+q];
                sample(v+axis*b[1]+side*(b[0]*(gap+b[1])/std::max(1.,gap)),1.);
            }
        }
        int h=std::min(H,std::max(3,int(gap/800.)+2));const auto &enemy=actor[target];
        sample(v,p.st==S_RECALL?4.:1.);
        for(int m:{0,1,5,10,13,14,15})sample(enemy.path[m][h],enemy.weight[m]*4.);
        V best{};quality=0;
        for(int off=-2200;off<=2200;off+=100){
            V ray=(v+side*off-origin).unit(),stop=origin+ray*std::min<double>(cf.range,gap+2200);
            i64 x=0,y=0;
            if(seg_wall(live,origin.x,origin.y,stop.x,stop.y,x,y))stop={double(x),double(y)};
            double value=0;
            for(int i=0;i<count;i++)value+=weights[i]*clip((radius+40-swept(origin-samples[i],stop-samples[i]))/290.,0.,1.);
            if(value>quality){quality=value;best=ray;}
        }
        quality/=total;return best;
    }
    int followFire=-1;V fireMovement;
    void attackFromCover(const Obs &o,Action &a){
        compactCourt();
        if(o.me().st==S_THROW && t==followFire){a=command(fireMovement);return;}
        if(court.empty() || actor[target].hidden || o.me().st!=S_FREE || o.my_dart().st!=D_HAND)return;
        const auto &e=o.p[target];const auto &d=o.d[target];
        V v=pos(e);double r=(v-me).len();
        const bool armed=d.st==D_HAND;
        if(t-courtStart<130 || e.st==S_THROW || dart_flying(d.st) || r<1700)return;
        if(a.act==A_THROW){
            if(r>2450 && e.st!=S_DASH && !los(me,v)){
                V m=V{double(a.mx),double(a.my)}*.001;
                Body b{o.me().x,o.me().y,o.me().vx,o.me().vy};
                for(int z=0;z<cf.throw_pre;z++)move(b,m*(cf.run_v*.5));
                double prob=0;V aim=compactShot(o,pos(b),prob);
                if(prob>.73 && cell(pos(b),2)!=C_PIT){a=command(m,A_THROW,aim);followFire=t+1;fireMovement=m;}
            }
            return;
        }
        bool idle=e.st==S_RECALL || d.st==D_RISE || d.st==D_GROUND;
        if(!idle && !armed)return;
        int frame=std::max<int>(0,t-cf.delay);double wander=0;
        for(int age:{3,6,9,12}){
            if(age>frame)continue;
            const auto &q=trail[target][(frame-age)%TRAIL];
            if(q.frame==frame-age)wander=std::max(wander,(q.p-v).len());
        }
        bool entrenched=wander<420 && e.st!=S_DASH;
        if(armed && a.act!=A_NONE)return;
        if(r<7300 && r>1700){
            V m=idle?V{}:V{double(a.mx),double(a.my)}*.001;
            Body b{o.me().x,o.me().y,o.me().vx,o.me().vy};
            for(int z=0;z<cf.throw_pre;z++)move(b,m*(cf.run_v*.5));
            double prob=0;V aim=compactShot(o,pos(b),prob);
            if(entrenched && idle){
                V direct=(v-pos(b)).unit();
                if(los(pos(b),v-direct*(radius-310))){aim=direct;prob=.98;}
            }
            if(cell(pos(b),3)!=C_PIT && prob>(armed?.87:.71)){
                a=command(m,A_THROW,aim);followFire=t+1;fireMovement=m;return;
            }
        }
        if(armed && (los(me,v) || r<2400))return;
        if(idle && a.act==A_MELEE && (pos(d)-me).len()<1150 && !entrenched)return;
        if(t>=nextRoute || (v-routeVictim).len()>700 || !usableWaypoint || (me-waypoint).len()<170)findLane(v,armed);
        if(!usableWaypoint)return;
        V dir=waypoint-me;
        V m=dir.unit()*std::min(1.,dir.len()/cf.run_v);
        Body b{o.me().x,o.me().y,o.me().vx,o.me().vy};move(b,m*cf.run_v);
        if(cell(pos(b),1)!=C_PIT && (dir.len()-(pos(b)-waypoint).len())>-15)a=command(m);
    }

    // Compare commitment times and approach directions with the real engine.
    // A clash is valuable when the owner survives and wins the pickup race.
    int interceptFire=-1, interceptExpiry=-1;
    V interceptMove,interceptRay;
    void planOpeningClash(const Obs &o,Action &a){
        if(court.empty() || o.my_dart().st==D_GONE || actor[target].hidden)return;
        const auto &mine=o.my_dart();const auto &p=o.me();
        if(t>0){
            if(t>interceptExpiry || (t>cf.delay && o.p[target].st==S_FREE && o.d[target].st==D_HAND))return;
            if(t<=interceptFire+1){
                a=command(interceptMove,t==interceptFire?A_THROW:A_NONE,interceptRay);return;
            }
            if(mine.st==D_GROUND){
                V m=(pos(mine)-me).unit();
                Body b{p.x,p.y,p.vx,p.vy};move(b,m*(p.st==S_THROWN?cf.run_v*.5:cf.run_v));
                if(cell(pos(b),1)!=C_PIT)a=command(m);
                return;
            }
            if(mine.st==D_OUT && p.st==S_THROWN){
                Body b{p.x,p.y,p.vx,p.vy};move(b,interceptMove*(cf.run_v*.5));
                if(cell(pos(b),1)!=C_PIT)a=command(interceptMove);
            }
            return;
        }
        V v=pos(o.p[target]),delta=v-me,axis=delta.unit(),side=axis.side();double gap=delta.len();
        if(gap<1650 || gap>4450 || !los(me,v))return;
        Game initial(info(),o);initial.LM();
        double best=53;
        for(int d=0;d<12;d++){
            V m=axis*dirs[2*d].x+side*dirs[2*d].y;
            for(int when=0;when<4;when++){
                Body b{p.x,p.y,p.vx,p.vy};bool safe=true;
                for(int h=0;h<when+cf.throw_pre;h++){
                    move(b,m*(cf.run_v*(h>=when?.5:1.)));
                    if(cell(pos(b),h+1)==C_PIT)safe=false;
                }
                if(!safe)continue;
                V ray=(v-pos(b)).unit();double sum=0,worst=1e20;
                for(int mode=0;mode<5;mode++){
                    Game g=initial;double score=0;int pickup=20,hispick=20;
                    V strafe=mode==0?side:mode==1?side*(-1):mode==2?(side-axis*.4).unit():
                             mode==3?(side*(-1)-axis*.4).unit():(home-v).unit();
                    V shot=(me-v-strafe*(mode<2?0.:cf.run_v)).unit();
                    for(int h=0;h<11;h++){
                        auto &self=g.p[s];auto &enemy=g.p[target];
                        V ours=m;
                        if(g.d[s].st==D_GROUND)ours=(pos(g.d[s])-pos(self)).unit();
                        if(pickup<20)ours={};
                        Action x[MAXP]{};x[s]=command(ours,h==when?A_THROW:A_NONE,ray);
                        V heading=strafe;
                        if(g.d[target].st==D_GROUND)heading=(pos(g.d[target])-pos(enemy)).unit();
                        if(cell(pos(enemy)+heading*cf.run_v,h)==C_PIT)heading={};
                        x[target]=command(heading,h==(mode==4?1:0)?A_THROW:A_NONE,shot);
                        if(h>=5 && !enemy.cd && mode==3 && g.d[target].st==D_GROUND &&
                           (pos(g.d[target])-pos(enemy)).len()>1600)
                            x[target]=command({},A_DASH,heading);
                        g.step(x);
                        if(!g.p[s].alive || !g.p[target].alive)break;
                        if(g.p[s].n_pick && pickup==20)pickup=h;
                        if(g.p[target].n_pick && hispick==20)hispick=h;
                        if(pickup<20 && hispick<20)break;
                    }
                    if(!g.p[s].alive)score=-135;
                    else if(!g.p[target].alive)score=125;
                    else if(!g.p[s].n_clash)score=-56;
                    else{
                        double dist=(pos(g.p[target])-pos(g.d[target])).len();
                        score=pickup<20?48+clip(hispick-pickup,-7.,6.)*8+(9-pickup)*2:-35;
                        if(pickup<20 && hispick==20)score+=std::min(24.,dist*.009);
                        if(hispick<pickup)score-=60;
                    }
                    sum+=score;worst=std::min(worst,score);
                }
                double score=sum*.2+worst*.3;
                if(score>best){best=score;interceptMove=m;interceptRay=ray;interceptFire=when;interceptExpiry=when+10;}
            }
        }
        if(interceptFire>=0)a=command(interceptMove,interceptFire==0?A_THROW:A_NONE,interceptRay);
    }

    // The first moving tick of a newly released dart is after both windup
    // ticks. Test for a swept clash there and on the following two ticks.
    int sweepUntil=-1,pickUntil=-1;
    V sweepDir;
    void counterIncomingDart(const Obs &o,Action &a){
        if(target<0 || actor[target].hidden)return;
        const auto &p=o.me(),&e=o.p[target];const auto &d=o.d[target];
        if(t<=sweepUntil && p.st==S_THROW){a=command(sweepDir);return;}
        if(t<=pickUntil && o.my_dart().st==D_GROUND && (pos(o.my_dart())-me).len()<1250 &&
           (pos(e)-me).len()>3500){
            V dir=(pos(o.my_dart())-me).unit();
            Body b{p.x,p.y,p.vx,p.vy};move(b,dir*(p.st==S_THROWN?cf.run_v*.5:cf.run_v));
            if(cell(pos(b),1)!=C_PIT && los(me,pos(o.my_dart()))){a=command(dir);return;}
        }
        if(t<cf.delay || p.st!=S_FREE || o.my_dart().st!=D_HAND || a.act==A_THROW ||
           (e.st!=S_THROW && d.st!=D_OUT) || (pos(e)-me).len()<3300)return;
        V start[7],finish[7];bool exists[7]{};
        for(int h=1;h<=6;h++)for(const auto &f:flights[h])if(f.k==target && f.model==0){
            start[h]=f.a;finish[h]=f.b;exists[h]=(f.b-f.a).len()>100;break;
        }
        if(!exists[3])return;
        V line=(finish[3]-start[3]).unit();
        if((me-start[3]).dot(line)<-1200 || (start[3]-me).len()>3300)return;
        double best=0;V cast{},moveDir{};
        for(V m:{(start[3]-me).unit(),line*(-1),line.side(),line.side()*(-1),V{a.mx*.001,a.my*.001},V{}}){
            Body b{p.x,p.y,p.vx,p.vy};V path[7];path[0]=me;bool safe=true;
            for(int h=1;h<=6;h++){
                move(b,m*(cf.run_v*(h<=4?.5:1.)));path[h]=pos(b);
                if(cell(path[h],h)==C_PIT)safe=false;
            }
            if(!safe)continue;
            for(int h=1;h<=2;h++)if(exists[h] && swept(start[h]-path[h-1],finish[h]-path[h])<radius+180)safe=false;
            if(!safe)continue;
            for(int expect=3;expect<=5 && exists[expect];expect++){
                V ray=((start[expect]+finish[expect])*.5-path[2]).unit(),our=path[2];
                for(int h=3;h<=expect;h++){
                    if(!exists[h])break;
                    V end=our+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(h-3)*cf.dart_dec);
                    if(!los(our,end))break;
                    V delta=our-start[h],change=(end-our)-(finish[h]-start[h]);
                    double part=clip(-delta.dot(change)/std::max(1.,change.dot(change)),0.,1.);
                    double miss=(delta+change*part).len();
                    if(delta.len()>2*cf.dart_r && miss<2*cf.dart_r-150){
                        V hit=our+(end-our)*part,stop=start[h]+(finish[h]-start[h])*part;
                        if(swept(start[h]-path[h-1],stop-path[h])<radius+180 || cell(hit,h)==C_WALL)break;
                        double pickup=(hit-path[h]).len();
                        if(pickup>1250 || !los(path[h],hit) || (hit-pos(e)).len()<3100)break;
                        Body catchBody{std::lround(path[h].x),std::lround(path[h].y),0,0};int needed=0;
                        while((hit-pos(catchBody)).len()>cf.pick_r-35 && needed<5){
                            move(catchBody,(hit-pos(catchBody)).unit()*(cf.run_v*(h+needed<4?.5:1.)));
                            if(cell(pos(catchBody),h+needed+1)==C_PIT){needed=9;break;}
                            needed++;
                        }
                        if(needed<=3){
                            double value=3.8-needed+.5*(1.-miss/(2*cf.dart_r))+.15*(5-h);
                            if(value>best){best=value;moveDir=m;cast=ray;}
                        }
                        break;
                    }
                    if(swept(start[h]-path[h-1],finish[h]-path[h])<radius+180)break;
                    our=end;
                }
            }
        }
        if(best>.9){a=command(moveDir,A_THROW,cast);sweepDir=moveDir;sweepUntil=t+1;pickUntil=t+8;}
    }

    // Evidence accumulates while a visible, armed opponent closes slowly on
    // clear ground. A recent ranged attack resets the melee-spacing response.
    double patientSteps=0;
    V counterMove;
    int confirmedUntil=-1;
    int counterUntil=-1, recentThrow=-1000, deadCalls=0;
    V lastDrop;
    void adjustMeleeSpacing(const Obs &o,Action &a){
        const auto &p=o.p[target], &own=o.me();const auto &dart=o.d[target];
        // A clash is earlier than the delayed view. It rules out pursuing
        // a melee specialist, but keep the normal ranged policy's own memory.
        if(contactFrame==t && contact==DartClash){
            lastProjectile=t;slowEvidence=-1;wideGuardUntil=-1;
        }
        if(p.vis && (p.st==S_THROW || dart_flying(dart.st))){
            recentThrow=t;lastProjectile=t;patientSteps=0;slowEvidence=-1;wideGuardUntil=-1;
        }
        if(!p.vis || !p.alive || t-recentThrow<160 || dart.st!=D_HAND)return;
        if(o.my_dart().st==D_HAND)deadCalls=0;
        if(t>0 && o.my_dart().st==D_GROUND){
            if(histD[(t-1)%HISTORY].st==D_CALL && (lastDrop-pos(o.my_dart())).len()<1500)deadCalls++;
            if(histD[(t-1)%HISTORY].st!=D_GROUND)lastDrop=pos(o.my_dart());
        }
        double speed=vel(p).len(),r=(pos(p)-me).len();
        V toward=(pos(history[std::max<int>(0,t-cf.delay)%HISTORY])-pos(p)).unit();
        bool clear=los(me,pos(p));
        if(t>cf.delay && p.st==S_FREE && r<12000 && r>2250){
            bool moderate=speed>40 && speed<cf.run_v*.89;
            bool clearFloor=!circle_hits_wall(live,cf.body_r+140,p.x,p.y);
            bool closing=vel(p).dot(toward)>speed*.10;
            if(moderate && clearFloor && closing)patientSteps=std::min(32.,patientSteps+1.6);
            else if(moderate && clearFloor && clear)patientSteps=std::min(32.,patientSteps+.35);
            else patientSteps=std::max(0.,patientSteps-(p.cd?.08:.38));
        }

        int stamp=std::max<int>(0,t-cf.delay);
        int measured=0;
        // Consecutive submaximal steps on clear floor distinguish a deliberate
        // slow approach from the single braking tick of a full-speed turn.
        for(int h=0;h<26 && stamp-h>0;h++){
            const auto &cur=trail[target][(stamp-h)%TRAIL],&last=trail[target][(stamp-h-1)%TRAIL];
            if(cur.frame!=stamp-h || last.frame!=stamp-h-1 || cur.state!=S_FREE || last.state!=S_FREE ||
               cur.dart!=D_HAND || last.dart!=D_HAND)continue;
            double speed=cur.v.len(),prior=last.v.len();
            if(speed<40 || speed>cf.run_v*.88 || prior<40 || prior>cf.run_v*.93 ||
               cur.v.dot(last.v)<speed*prior*.72 || circle_hits_wall(live,cf.body_r+95,cur.p.x,cur.p.y))continue;
            if(cur.v.dot((cur.observer-cur.p).unit())>-speed*.15)measured++;
        }
        if(measured>=3)confirmedUntil=t+100;
        bool concealed=cell(me)==C_GRASS && own.expose==0 && r>cf.see_r+250;
        if(concealed && clear && r>2900 && r<6500 && stillTime[target]>=9 && measured>=1){
            patientSteps=std::max(patientSteps,12.);confirmedUntil=t+45;
        }
        if(target!=styleRival){
            styleRival=target;wideGuardUntil=-1;slowEvidence=0;lastAttackWitness=-100;
        }
        // At frame u the ground dart is already visible to us. Four ticks
        // later the defender's observed recovery timer dates its actual swing.
        if(contact==EnemyParry && contactFrame==stamp && contactFrame!=lastAttackWitness &&
           p.st==S_SLASHED && p.timer<cf.slash_post && p.timer>=cf.slash_post-4 &&
           (pos(p)-stoppedDart).len()<reach+280){
            wideGuardUntil=t+450;lastAttackWitness=contactFrame;
        }
        int steady=0;
        for(int h=0;h<12 && stamp-h>=2;h++){
            const auto &u=trail[target][(stamp-h)%TRAIL],&v=trail[target][(stamp-h-1)%TRAIL],&w=trail[target][(stamp-h-2)%TRAIL];
            if(u.frame!=stamp-h || v.frame!=u.frame-1 || w.frame!=u.frame-2 || u.state!=S_FREE ||
               v.state!=S_FREE || w.state!=S_FREE || u.dart!=D_HAND || (u.observer-u.p).len()<1800)continue;
            double speed=u.v.len(),prev=v.v.len();
            if(speed<20 || speed>cf.run_v*.88 || prev<15 || prev>cf.run_v*.98 ||
               speed<.5*prev || speed>1.15*prev || (u.v-v.v).len()>cf.acc*.26 ||
               (v.v-w.v).len()>cf.acc*.60 || u.v.dot(v.v)<speed*prev*.55 ||
               u.v.dot((u.observer-u.p).unit())<speed*.30 || circle_hits_wall(live,cf.body_r+65,u.p.x,u.p.y))continue;
            steady++;
        }
        if(steady>=2)slowEvidence=t+210;
        bool closeRush=p.st==S_DASH && r<5650 && clear &&
            (pos(history[stamp%HISTORY])-pos(p)).unit().dot(V{p.ax*.001,p.ay*.001})>.82;
        bool contested=contact==EnemyParry && contactFrame==t && o.my_dart().st==D_GROUND &&
            own.cd==0 && r>1800 && r<5150 && (pos(o.my_dart())-me).len()<2500 &&
            clear && los(me,pos(o.my_dart()));
        if(enemyShotCount[target]==0 && (!travelDash[target] || parries>=2)){
            if(closeRush)wideGuardUntil=std::max(wideGuardUntil,t+8);
            if(contested)wideGuardUntil=std::max(wideGuardUntil,t+24);
        }
        bool presses=wideGuardUntil>=t || slowEvidence>t;
        if(presses && r<=12500 && t-lastProjectile>=160){
            pressGuard(o,a,p,own,clear);
            return;
        }
        if(t>confirmedUntil || patientSteps<7 || r>10000 || (!clear && p.st!=S_DASH))return;
        V center=pos(p)+avgMove[target]*2.,forward=(center-me).unit();
        bool rushing=p.st==S_DASH;
        if(rushing){
            Body b{p.x,p.y,p.vx,p.vy};
            V aim=V{double(p.ax),double(p.ay)}.unit();
            for(int z=p.timer;z>0;z--){
                if(z<=cf.dash_t+cf.dash_post && z>cf.dash_post)move(b,aim*cf.dash_v,true);
                else move(b,{},true);
            }
            center=pos(b);forward=(center-me).unit();
        }
        if(t<counterUntil && (own.st==S_THROW || own.st==S_THROWN)){a=command(counterMove);return;}
        if(own.st==S_RECALL){
            double dist=(me-center).len();
            if(!rushing && (dist>5300 || (own.timer<=4 && dist>4450)))a={};
            return;
        }
        if(own.st!=S_FREE)return;
        bool held=o.my_dart().st==D_HAND;
        double desired=held?7200:5700;
        V direction{};double best=-1e20;
        for(int j=-1;j<int(dirs.size());j++){
            V m=j<0?V{}:dirs[j];
            Body b{own.x,own.y,own.vx,own.vy};
            bool valid=true;double score=0;
            for(int h=1;h<=9;h++){
                move(b,m*cf.run_v);
                int id=index(pos(b));
                if(id<0 || cell(pos(b),h+3)==C_PIT){valid=false;break;}
                double gap=(pos(b)-center).len();
                score-=std::abs(gap-desired)*.12+std::max(0.,(held?3250:4050)-gap)*.12;
                score+=std::min(border[id],4)*13;
                if(!held && o.my_dart().st==D_GROUND && gap>3000)score-=(pos(b)-pos(o.my_dart())).len()*.046;
            }
            if(!valid)continue;
            score-=(pos(b)-home).len()*.055;
            if(score>best){best=score;direction=m;}
        }
        double gap=(center-me).len();
        bool drawAcross=!held && o.my_dart().st==D_GROUND && deadCalls>=2 &&
            (pos(o.my_dart())-center).len()>1050 && gap>4400 && gap<7700;
        if(!drawAcross && !held && !rushing && gap>5000 && a.act==A_RECALL)return;
        if(!held && gap<1950 && a.act==A_MELEE)return;
        if(!drawAcross && !held && o.my_dart().st==D_GROUND && gap>4700 && (pos(o.my_dart())-me).len()>3200 && los(me,center)){
            a=command({},A_RECALL);return;
        }
        if(held && rushing && gap<=2400 && los(me,center)){
            V m=gap>1450?forward:forward*(-1.);
            Body b{own.x,own.y,own.vx,own.vy};
            for(int k=0;k<cf.throw_pre;k++)move(b,m*(cf.run_v*.5));
            if(cell(pos(b),3)!=C_PIT){
                counterUntil=t+cf.throw_pre+cf.throw_post;counterMove=m;
                a=command(m,A_THROW,(center-pos(b)).unit());return;
            }
        }
        bool canRetreat=direction.dot(forward)<-.35 && best>-1e19;
        if(held && !rushing && gap<8200 && gap>1600 && los(me,center) &&
           (!canRetreat || gap>5350 || p.cd>cf.delay+3)){
            Body b{own.x,own.y,own.vx,own.vy};
            for(int k=0;k<cf.throw_pre;k++)move(b,direction*(cf.run_v*.5));
            if(cell(pos(b),3)!=C_PIT){
                V victim=pos(p)+avgMove[target]*3.;
                counterUntil=t+cf.throw_pre+cf.throw_post;counterMove=direction;
                a=command(direction,A_THROW,(victim-pos(b)).unit());return;
            }
        }
        if(!held && own.cd==0 && (gap<4350 || drawAcross) && best>-1e19){
            double win=0;V evasion;
            for(V m:dirs){
                Body b{own.x,own.y,own.vx,own.vy};
                for(int i=0;i<cf.dash_t;i++)move(b,m*cf.dash_v,true);
                int j=index(pos(b));if(j<0 || cell(pos(b),8)==C_PIT || cell(pos(b)+m*150,10)==C_PIT)continue;
                double value=(pos(b)-center).len()-gap+100*std::min(3,border[j]);
                if(drawAcross){
                    V line=pos(b)-center;
                    value=2200.-swept(center-pos(o.my_dart()),pos(b)-pos(o.my_dart()))*.75;
                    value-=std::abs(line.len()-6600)*.40;
                }
                if(value>win){win=value;evasion=m;}
            }
            if(win>900){a=command(evasion,A_DASH,evasion);if(drawAcross)deadCalls=0;return;}
        }
        if(best>-1e19)a=command(direction);
    }

    bool travelDash[MAXP]{};
    int lastProjectile=-1000;
    int styleRival=-1,wideGuardUntil=-1,slowEvidence=-1,lastAttackWitness=-100;
    void pressGuard(const Obs &o,Action &a,const Player &p,const Player &own,bool clear){
        V here=pos(p),v=avgMove[target];
        const auto &d=o.my_dart();bool held=d.st==D_HAND;
        bool dash=p.st==S_DASH;
        if(dash){
            V dir={p.ax*.001,p.ay*.001};
            Body b{p.x,p.y,p.vx,p.vy};
            for(int h=0;h<=cf.delay+2;h++){
                int left=p.timer-h;
                if(left>cf.dash_post && left<=cf.dash_post+cf.dash_t)move(b,dir*cf.dash_v,true);
                else move(b,{});
            }
            here=pos(b);v={};
        }else if(p.st==S_FREE && los(here,here+v*3))here=here+v*3;
        double gap=(here-me).len();
        V point=here;
        if(!clear && !dash)return;
        if(d.st==D_GROUND)point=pos(d);
        V dir=(point-me).unit();
        if(own.st==S_STUN)return;
        // Date the five active melee ticks from the visible swing and its recovery.
        int swing=-1000,f=std::max<int>(0,t-cf.delay);
        if(p.st==S_SLASH)swing=f-(cf.slash_pre-p.timer);
        if(p.st==S_SLASHED)swing=f-(cf.slash_pre+cf.slash_post-p.timer);
        bool wardActive=t-swing>=0 && t-swing<=4;
        if(swing>0 && t-swing<10){here=pos(p);gap=(here-me).len();}
        
        if(p.st==S_STUN && p.timer>=cf.delay+2 && held && own.st==S_FREE){
            // Kick slide is deterministic until recovery, including wall friction.
            Player moving=p;V positions[18];
            for(int h=-int(cf.delay);h<18;h++){
                if(h>=0)positions[h]=pos(moving);
                if(moving.timer<=0)continue;
                move_body(live,cf.body_r,moving.x,moving.y,moving.vx,moving.vy);
                moving.vx=rdiv(moving.vx*cf.kick_keep,1000);
                moving.vy=rdiv(moving.vy*cf.kick_keep,1000);moving.timer--;
            }
            double best=-1e20;V direction,ray;
            for(V m:{V{},(positions[4]-me).unit(),(home-me).unit()}){
                Body b{own.x,own.y,own.vx,own.vy};V origin;bool ok=true;
                for(int h=1;h<=cf.throw_pre+cf.throw_post;h++){
                    move(b,m*(cf.run_v*cf.throw_move*.01));if(cell(pos(b),h)==C_PIT)ok=false;
                    if(h==cf.throw_pre)origin=pos(b);
                }
                if(!ok)continue;
                double run=0;
                for(int h=cf.throw_pre+1;h<15 && h<=p.timer-cf.delay+2;h++){
                    double step=std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);
                    V q=positions[h],u=(q-origin).unit();double r=(q-origin).len();
                    double miss=std::max({run-r,r-run-step,0.});
                    V end=origin+u*std::min(r,run+step);
                    double value=radius-miss-h*4;
                    if(miss<radius-80 && value>best && los(origin,end-u*std::min(300.,step*.4))){
                        best=value;direction=m;ray=u;
                    }
                    run+=step;
                }
            }
            if(best>0){a=command(direction,A_THROW,ray);return;}
            return;
        }
        auto safe=[&](V direction,int horizon,bool sprint){
            Body b{own.x,own.y,own.vx,own.vy};
            for(int h=1;h<=horizon;h++){
                bool air=sprint && h>cf.dash_pre && h<=cf.dash_pre+cf.dash_t;
                move(b,air?direction*cf.dash_v:sprint?V{}:direction*cf.run_v,air);
                if(air && h==cf.dash_pre+cf.dash_t){
                    b.vx=rdiv(b.vx*cf.run_v,cf.dash_v);b.vy=rdiv(b.vy*cf.run_v,cf.dash_v);
                }
                if((!air || h==cf.dash_pre+cf.dash_t) && cell(pos(b),h+1)==C_PIT)return false;
            }
            int id=index(pos(b));
            return id>=0 && jumpLatest[id]>=t+horizon && cell(pos(b),horizon+5)!=C_PIT;
        };
        bool chase=held || dart_flying(d.st) || (d.st==D_GROUND && (pos(d)-me).len()<gap+400 && (pos(d)-me).len()<4450);
        if(!chase){
            if(gap>4550 && cell(me,cf.recall_pre+3)!=C_PIT && !dash){a={};if(own.st==S_FREE)a.act=A_RECALL;}
            return;
        }
        if(own.st==S_RECALL && (pos(d)-me).len()>1750 && gap>3900){a={};return;}
        if(own.st==S_DASH){
            a={};
            if(own.timer>cf.dash_post && own.timer<=cf.dash_post+cf.dash_t){
                Body stop{own.x,own.y,own.vx,own.vy};
                bool safeStop=true;
                for(int h=0;h<cf.slash_pre;h++){move(stop,{});if(cell(pos(stop),h+1)==C_PIT)safeStop=false;}
                V strike=here-pos(stop);
                if(safeStop && strike.len()<reach-80 && los(pos(stop),here) &&
                   (held || p.st!=S_STUN) && cell(pos(stop),2)!=C_PIT)
                    a=command({},A_MELEE,strike.unit());
            }
            return;
        }
        V pursuit=dir;
        if(!safe(pursuit,5,false)){
            double best=-1e30;for(V m:dirs)if(safe(m,6,false)){
                double value=m.dot(dir)*1350+(home-me).unit().dot(m)*220;
                if(value>best){best=value;pursuit=m;}
            }
            if(best<-1e29)return;
        }
        if(own.st==S_RECALL || own.st==S_THROW || own.st==S_THROWN){a=command(pursuit);return;}
        if(own.st!=S_FREE)return;
        if(wardActive && !held && own.cd==0 && gap<2200 &&
           (swing+4>=t+2)){
            V out;double best=0;
            for(V h:dirs)if(safe(h,8,true)){
                double gain=h.dot((me-here).unit())+.40*h.dot((home-me).unit());
                if(gain>best){best=gain;out=h;}
            }
            if(best>.55){a=command({},A_DASH,out);return;}
        }
        if(gap<reach-100 && (held || !(p.st==S_STUN)) && los(me,here)){
            a=command({},A_MELEE,(here-me).unit());return;
        }
        if(!held && d.st==D_OUT && !own.cd && p.st!=S_DASH && own.st==S_FREE && gap<4800 && (here-me).dot(vel(d).unit())>2200){
            V run=(here-me).unit();
            if(safe(run,8,true)){a=command({},A_DASH,run);return;}
        }
        if(!held && d.st==D_GROUND && (pos(d)-me).len()>1400 && (pos(d)-me).len()<3950 && own.cd==0 && safe(dir,8,true)){
            a=command({},A_DASH,dir);return;
        }
        double span=cf.dash_v*cf.dash_t+reach;
        double basic=cf.dart_v*4.25;
        double envelope=basic+2*(span-5.0*cf.dart_v);
        envelope=clip(envelope,2.60*cf.dart_v,6.0*cf.dart_v);
        double closing=avgMove[target].dot((me-pos(p)).unit());
        envelope+=clip(closing,-180.,180.)*.4;
        if(held && ((gap<envelope && gap>1000) || dash) && los(me,here)){
            V victim=here+v*(gap<3500?1.:2.);
            if(!dash && gap>2000 && gap<5000){
                V line=(here-me).unit(),transverse=line.side()*v.dot(line.side());
                victim=here+transverse*2+line*clip(v.dot(line),-125.,125.);
            }
            Body b{own.x,own.y,own.vx,own.vy};
            for(int h=0;h<cf.throw_pre;h++)move(b,pursuit*(cf.run_v*.5));
            if(cell(pos(b),3)!=C_PIT){a=command(pursuit,A_THROW,(victim-pos(b)).unit());return;}
        }
        if(held && !dash && parries==0 && gap>envelope+650){
            if(a.act==A_DASH || a.act==A_MELEE)return;
            V suggested={a.mx*.001,a.my*.001};
            if(suggested.len()>.10 && safe(suggested.unit(),4,false)){
                a=command(suggested.unit());return;
            }
            a=command(suggested);return;
        }
        a=command(pursuit);
    }
    int slidePhase=-999;
    std::vector<signed char> slideRisk;
    bool unsafeSlide(V point,int dir){
        int x=int((point.x-courtX)/mesh),y=int((point.y-courtY)/mesh);
        if(x<0 || x>=courtW || y<0 || y>=courtH)return true;
        if(slidePhase!=phase || slideRisk.size()!=court.size()*24){
            slideRisk.assign(court.size()*24,-1);slidePhase=phase;
        }
        int j=y*courtW+x;int k=j*24+dir;
        auto &cached=slideRisk[k];
        if(cached<0){
            V start=nodePos(j);Player p{};p.x=start.x;p.y=start.y;
            p.vx=std::lround(dirs[dir].x*cf.kick_v);p.vy=std::lround(dirs[dir].y*cf.kick_v);p.timer=cf.kick_stun;
            V stop=stunEnd(p);cached=cell(stop,cf.kick_stun)==C_PIT;
        }
        return cached!=0;
    }
    double edgeThreat(V point,V foe,int h,const Obs &o){
        V line=point-foe;double distance=line.len();
        if(distance>5000 || !los(foe,point))return 0;
        int center=int(std::lround(std::atan2(line.y,line.x)*(24./6.28318530718)))+24;
        double risk=0;
        for(int i=-2;i<=2;i++)risk+=unsafeSlide(point,(center+i+24)%24)*(i==0?.38:std::abs(i)==1?.23:.08);
        double reach=clip((2850-distance)/1150.,0.,1.);
        if(o.p[target].cd<=cf.delay+h)
            reach=std::max(reach,.50*clip((4700-distance)/1700.,0.,1.));
        return risk*reach;
    }
    // The pickup race needs enough time to finish before a second enemy can
    // contest the drop. A projectile already on its way also vetoes it.
    void counterInCrowd(const Obs &o,Action &a){
        if(cf.mode!=1 || aliveEnemies<2 || target<0)return;
        int focus=-1;double closest=1e10;
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy && !actor[k].hidden &&
                (o.p[k].st==S_THROW || o.d[k].st==D_OUT)){
            for(int h=1;h<=5;h++)for(const auto &f:flights[h])if(f.model==0 && f.k==k){
                double d=swept(f.a-me,f.b-me);
                if(d<closest && d<2000){closest=d;focus=k;}
            }
        }
        if(focus<0)return;
        for(int k=0;k<n;k++)if(actor[k].valid && actor[k].enemy && k!=focus){
            V enemy=actor[k].path[0][4];double d=(enemy-me).len();
            if(los(enemy,me) && d<(actor[k].weapon[6]?5900:3900))return;
            for(int h=1;h<=7;h++)for(const auto &f:flights[h])
                if(f.k==k && f.model==0 && swept(f.a-me,f.b-me)<2300)return;
        }
        int prior=target;target=focus;counterIncomingDart(o,a);target=prior;
    }

    void finishInCrowd(const Obs &o,Action &a){
        if(cf.mode!=1 || aliveEnemies<2 || o.me().st!=S_FREE || o.my_dart().st!=D_HAND ||
           a.act==A_DASH || a.act==A_MELEE || a.act==A_THROW)return;
        const Player &p=o.me();V m={a.mx*.001,a.my*.001};Body b{p.x,p.y,p.vx,p.vy};
        V origin;
        for(int h=1;h<=cf.throw_pre+cf.throw_post;h++){
            move(b,m*(cf.run_v*.5));if(cell(pos(b),h+2)==C_PIT)return;
            for(const auto &f:flights[h])if(f.model==0 && swept(f.a-pos(b),f.b-pos(b))<radius+400)return;
            if(h==cf.throw_pre)origin=pos(b);
        }
        double best=0.94;V shot;
        for(int k=0;k<n;k++)if(k!=s && actor[k].valid && !actor[k].hidden){
            const auto &e=actor[k];V q=e.oldpos;double gap=(q-origin).len();
            if(gap<1800 || gap>6500 || !los(origin,q))continue;
            bool exposed=o.p[k].st==S_STUN || o.p[k].st==S_RECALL ||
               (!e.weapon[3] && !e.weapon[7]) || (o.p[k].st==S_DASH && o.p[k].cd>cf.delay+4);
            if(!exposed && (preferredEnemy[k]==s || nearestOther[k]>4500))continue;
            double risk=0;
            for(int u=0;u<n;u++)if(u!=k && actor[u].valid && actor[u].enemy){
                V other=actor[u].path[0][3];double r=(other-origin).len();
                if(los(other,origin))risk=std::max(risk,clip(((actor[u].weapon[4]?7400.:4100.)-r)/3000.,0.,1.)*(.40+.60*attention[u][s]));
            }
            if(risk>.52)continue;
            int hit=std::min(12,int(gap/790)+2);
            for(int md:{0,1,5,10}){
                V aim=(e.path[md][hit]-origin).unit();double h0=0,h1=0;V f=origin;
                for(int h=cf.throw_pre+1;h<=12;h++){
                    V end=f+aim*std::max<i64>(cf.dart_vmin,cf.dart_v-cf.dart_dec*(h-cf.throw_pre-1));
                    if(!los(f,end) || clipClash(f,end,h))break;
                    double chance=0,extra=0;
                    for(int mm=0;mm<NMODEL;mm++){
                        double miss=swept(f-e.path[mm][h-1],end-e.path[mm][h]);
                        chance+=e.weight[mm]*clip((radius+120-miss)/350.,0.,1.);
                    }
                    for(int u=0;u<n;u++)if(u!=k && actor[u].valid && actor[u].enemy && !actor[u].hidden){
                        double r=swept(f-actor[u].path[0][h-1],end-actor[u].path[0][h]);
                        extra=std::max(extra,clip((radius-r)/380.,0.,1.));
                    }
                    double time=clip(1.-.15*std::max(0,h-std::max(5,e.freeAfter+1)),.28,1.);
                    h0=std::max(h0,chance*time);h1=std::max(h1,extra*time);
                    f=end;
                }
                double score=h0+.19*h1-risk*.65+((p.kills<o.p[k].kills)?.06:0);
                if(!exposed)score-=.27;
                if(score>best){best=score;shot=aim;}
            }
        }
        if(best>0.94)a=command(m,A_THROW,shot);
    }
