    static constexpr short laneRoots[]={0,365,692,1071,1432,};
    // Sample future positions relative to the defender and to the line of sight.
    void garrisonPaths(const Obs &o,V forecast[][13],double weights[]) const{
        int f=std::max<int>(0,t-cf.delay);
        const auto &e=o.p[target];V v=pos(e),axis=(v-me).unit(),side=axis.side();
        double cross=vel(e).dot(side);
        if((std::abs(cross)>30?cross:(home-v).dot(side))<0)side=side*(-1.);
        V seen=pos(history[f%HISTORY]);double x[53];int idx=0;
        auto add=[&](double a){x[idx++]=a;};
        auto pair=[&](V a){add(a.dot(axis));add(a.dot(side));};
        add((v-me).len());pair(vel(e));pair(vel(o.me()));pair(me-seen);pair(v-home);
        for(int lag:{1,3,6,9,14,20}){
            int when=std::max(0,f-lag);const auto &q=trail[target][when%TRAIL];
            pair(q.frame==when?v-q.p:V{});pair(seen-pos(history[when%HISTORY]));
        }
        for(V ray:{axis,axis*(-1.),side,side*(-1.),(axis+side)*.707,(axis-side)*.707,(side-axis)*.707,(axis+side)*(-.707)}){
            int count=0,cover=0;for(int d:{400,800,1200,1700,2400}){
                int j=index(v+ray*d);if(j<0 || !border[j])break;
                count++;cover+=int(live.c[j]==C_GRASS)+2*int(live.w[j]<0);
            }
            add(count);add(cover);
        }
        add(e.cd);add(o.me().cd);add(std::min<i64>(25,e.timer));add(std::min(25,f));
        int m=0;
        for(int root:laneRoots){
            int j=root;while(laneTree[j].f>=0){auto &z=laneTree[j];j=x[z.f]<=z.cut?z.l:z.r;}
            for(int q=0;q<3;q++,m++){
                const auto &row=laneLeaf[laneTree[j].l+q];weights[m]=1.;
                for(int h=0;h<=12;h++){
                    double age=h+std::min<int>(t,cf.delay);
                    double d=clip((age-6)*.5,0.,4.);int lo=int(d),hi=std::min(4,lo+1);
                    V p=v+(axis*(row[2*lo]*(1-d+lo)+row[2*hi]*(d-lo))+
                          side*(row[2*lo+1]*(1-d+lo)+row[2*hi+1]*(d-lo)))*std::min(1.,age/6.);
                    forecast[m][h]=footClear(p)?p:v;
                }
            }
        }
        for(int j:{0,1,5,10,13,15}){
            weights[m]=actor[target].weight[j]*5.+.12;
            for(int h=0;h<=12;h++)forecast[m][h]=actor[target].path[j][h];
            m++;
        }
    }
    int assaultUntil=-1,launch=-100,recoveryUntil=-1,swingTime=-1;
    V launchMove{},swingDir{};
    void breach(const Obs &o,Action &a){
        const auto &p=o.me(),&e=o.p[target];
        if(!occupied)return;
        if(claim>.40)assaultUntil=t+50;
        if(p.st==S_DASH && swingTime==t){
            V line=actor[target].path[0][std::min<int>(H,cf.slash_pre)]-me;
            if(line.len()>200 && line.unit().dot(swingDir)>.75)swingDir=(swingDir+line.unit()).unit();
            a=command({},A_MELEE,swingDir);return;
        }
        if(launch<t && t-launch<cf.throw_pre+cf.throw_post && (p.st==S_THROW || p.st==S_THROWN)){
            Body b{p.x,p.y,p.vx,p.vy};move(b,launchMove*(cf.run_v*.5));
            if(cell(pos(b),2)!=C_PIT)a=command(launchMove);return;
        }
        if(t>assaultUntil || !e.vis || e.st!=S_FREE || p.st!=S_FREE ||
           o.d[target].st!=D_HAND || o.my_dart().st!=D_HAND || t-recentThrow<48 ||
           (t<cf.delay && e.st!=S_FREE))return;
        V v=pos(e),axis=(v-me).unit(),side=axis.side();double r=(v-me).len();
        if(!los(me,v) || r<1300 || r>7800)return;
        V paths[21][13];double w[21],total=0;garrisonPaths(o,paths,w);
        for(double z:w)total+=z;
        V m=axis;double bestMove=-1e20;
        for(V dir:dirs){
            Body b{p.x,p.y,p.vx,p.vy};bool ok=true;double quality=0;
            for(int h=1;h<=6;h++){
                move(b,dir*cf.run_v);V at=pos(b);int j=index(at);
                if(j<0 || cell(at,h+2)==C_PIT || jumpLatest[j]<t+h+16){ok=false;break;}
                V future=v+avgMove[target]*std::min(3,h);double distance=(at-future).len();
                V prior=pos(history[std::max<int>(0,t-cf.delay)%HISTORY]);
                quality-=std::abs(distance-3100)*.55+.22*(at-home).len();
                quality+=std::min(850.,std::abs((at-prior).dot(side)))*0.97+std::min(4,border[j])*65;
            }
            if(ok && quality>bestMove){m=dir;bestMove=quality;}
        }
        if(bestMove<-1e19)return;
        double best=0;V aim{};int act=A_NONE,when=-1;V slash{};
        if(cf.dash_slash && !p.cd && r<cf.dash_v*cf.dash_t+reach+1450){
            for(int j=-12;j<=12;j++){
                V dir=(axis+side*(j*.085)).unit();Body run{p.x,p.y,p.vx,p.vy};bool ok=true;
                for(int h=1;h<=cf.dash_pre+cf.dash_t;h++){
                    if(h>cf.dash_pre){
                        int endh=h+cf.slash_pre-1;if(endh>12)break;
                        Body stop=run;bool safe=ok;
                        for(int z=h;z<=endh;z++){move(stop,{});if(cell(pos(stop),z+2)==C_PIT)safe=false;}
                        if(safe){
                            V center{};double close=0;
                            for(int k=0;k<21;k++){
                                V d=paths[k][endh]-pos(stop);double hit=clip((reach-45.-d.len())/360.,0.,1.);
                                center=center+d.unit()*(w[k]*hit);close+=w[k]*hit;
                            }
                            V facing=center.unit();double prob=0;
                            if(close>total*.43)for(int k=0;k<21;k++){
                                V q=paths[k][endh],line=q-pos(stop);double range=line.len();
                                if(range<reach && (range<cf.body_r || line.dot(facing)>range*(cf.slash_cos*.001+.06)) && los(q,pos(stop)))
                                    prob+=w[k]*clip((reach+20.-range)/280.,0.,1.)/total;
                            }
                            prob-=.064*std::max(0,endh-int(cf.delay)-1);
                            if(prob>0.66 && prob+0.08>best){
                                best=prob+0.08;aim=dir;act=A_DASH;when=t+h-1;slash=facing;
                            }
                        }
                    }
                    bool air=h>cf.dash_pre;move(run,air?dir*cf.dash_v:V{},air);
                    if(!air && cell(pos(run),h)==C_PIT)ok=false;
                }
            }
        }
        if(act==A_DASH){a=command({},act,aim);swingTime=when;swingDir=slash;}
        else if(a.act==A_NONE && r<6600)a=command(m);
    }
    void pursueParry(const Obs &o,Action &a){
        if(duelEnemy<0 || t-launch>18 || t<launch || target<0)return;
        const auto &p=o.me();
        if(contact==EnemyParry && contactFrame==t)recoveryUntil=t+cf.slash_post+3;
        if(t>recoveryUntil || contact!=EnemyParry || !o.p[target].vis)return;
        int elapsed=t-contactFrame;
        if(elapsed<0 || elapsed>cf.slash_post+2)return;
        V mark=stoppedDart;
        V foe=pos(o.p[target]);
        // The point of a successful block constrains even a delayed location.
        if((foe-mark).len()>reach)foe=mark+(foe-mark).unit()*(reach-50);
        bool held=o.my_dart().st==D_HAND,ground=o.my_dart().st==D_GROUND;
        if(!held && !ground)return;
        bool moving=p.st==S_DASH && p.timer>cf.dash_post && p.timer<=cf.dash_post+cf.dash_t;
        if(moving || p.st==S_FREE){
            Body b{p.x,p.y,p.vx,p.vy};bool safe=true;
            int pre=held?cf.slash_pre:cf.kick_pre;
            for(int h=1;h<=pre;h++){move(b,{});if(cell(pos(b),h)==C_PIT)safe=false;}
            V line=foe-pos(b);
            if(safe && line.len()<(held?reach:cf.kick_reach)-110 && los(pos(b),foe) &&
               elapsed+pre<=cf.slash_post+cf.slash_pre){
                a=command({},A_MELEE,line.unit());return;
            }
        }
        if(p.st==S_DASH)return;
        V point=held?foe:mark;
        double best=-1e30;Action choice;
        for(int mode=0;mode<2;mode++){
            bool sprint=mode!=0;
            if(sprint && (p.st!=S_FREE || p.cd>0))continue;
            if(!sprint && p.st!=S_FREE && p.st!=S_THROWN)continue;
            for(V pt:{point,foe,(point+foe)*.5}){
                V direction=(pt-me).unit();Body b{p.x,p.y,p.vx,p.vy};
                bool weapon=held;double score=-1e25;bool safe=true;
                for(int h=1;h<=cf.dash_pre+cf.dash_t+cf.dash_post;h++){
                    bool air=sprint && h>cf.dash_pre && h<=cf.dash_pre+cf.dash_t;
                    move(b,air?direction*cf.dash_v:sprint?V{}:direction*(cf.run_v*(p.st==S_THROWN && h<=p.timer?.5:1.)),air);
                    if(air && h==cf.dash_pre+cf.dash_t){
                        b.vx=rdiv(b.vx*cf.run_v,cf.dash_v);b.vy=rdiv(b.vy*cf.run_v,cf.dash_v);
                    }
                    if((!air || h==cf.dash_pre+cf.dash_t) && cell(pos(b),h+1)==C_PIT){safe=false;break;}
                    if((pos(b)-mark).len()<=cf.pick_r-30)weapon=true;
                    if(!weapon || elapsed+h+cf.slash_pre>cf.slash_post+cf.slash_pre+1 ||
                        !los(pos(b),foe))continue;
                    double d=(pos(b)-foe).len();
                    score=std::max(score,1250.-d-115*h+std::min(320.,(me-mark).len()-(pos(b)-mark).len()));
                }
                if(safe && score>best){choice=command(sprint?V{}:direction,sprint?A_DASH:A_NONE,direction);best=score;}
            }
        }
        if(best>-1100)a=choice;
    }
    int fastUntil=-1,waitingUntil=-1;
    void readPost(const Obs &o){
        if(!occupied || target<0 || !o.p[target].vis)return;
        int f=std::max<int>(0,t-cf.delay),freeSamples=0,fast=0;
        double speed=0;V first{},last{};
        for(int z=0;z<15 && z<=f;z++){
            const auto &v=trail[target][(f-z)%TRAIL];
            if(v.frame!=f-z || v.state!=S_FREE || v.dart!=D_HAND)continue;
            if(!freeSamples)first=v.p;
            last=v.p;freeSamples++;
            speed+=v.v.len();if(v.v.len()>cf.run_v*0.91)fast++;
        }
        if((fast>=4 && (first-last).len()>650) || (freeSamples>=4 && speed>freeSamples*cf.run_v*.80)){
            fastUntil=t+35;anchorUntil=-1;
        }
        if(freeSamples>=1 && speed<freeSamples*cf.run_v*.63 && fast<2 && t>fastUntil)
            waitingUntil=t+3;
    }
    int garrison=-1,anchorUntil=-1,siegeLaunch=-100,siegeDash=-100,sideSign=1;
    V anchor{};
    bool shortWalk(const Player &p,V m,int n,double speed) const{
        Body b{p.x,p.y,p.vx,p.vy};
        for(int h=1;h<=n;h++){move(b,m*speed);if(cell(pos(b),h+2)==C_PIT)return false;}
        return true;
    }
    void besiege(const Obs &o,Action &a){
        if(cf.mode>1 || duelEnemy<0 || target<0 || info().M().nwave==0 ||
           t>=wave_fall_step(cf,info().M().nwave-1))return;
        const auto &p=o.me(),&e=o.p[target];const auto &d=o.my_dart(),&his=o.d[target];
        if(!occupied && t>anchorUntil && t-siegeLaunch>17)return;
        int f=std::max<int>(0,t-cf.delay);
        if(garrison!=target){garrison=target;anchorUntil=-1;siegeLaunch=-100;siegeDash=-100;}
        int observations=0;V mean{};double speedSum=0;
        for(int z=0;z<=16 && z<=f;z++){
            const auto &u=trail[target][(f-z)%TRAIL];
            if(u.frame!=f-z || u.state!=S_FREE || u.dart!=D_HAND)continue;
            mean=mean+u.p;observations++;speedSum+=u.v.len();
        }
        if(observations)mean=mean*(1./observations);
        double width=0;
        for(int z=0;z<=16 && z<=f;z++){
            const auto &u=trail[target][(f-z)%TRAIL];
            if(u.frame==f-z && u.state==S_FREE && u.dart==D_HAND)width=std::max(width,(u.p-mean).len());
        }
        int id=index(mean);double territory=(home-mean).len();
        if(t>fastUntil && occupied && observations>=6 && speedSum<observations*cf.run_v*0.69 && e.vis && width<510 && id>=0 && refuge[id]>=0 &&
           (refuge[id]<27 || territory<2300) && (claim>.15 || ownedSteps>=6 ||
             (t<anchorUntil && (anchor-mean).len()<850))){
            anchorUntil=t+38;anchor=mean;
        }
        if(t>anchorUntil && t-siegeLaunch>15)return;
        V foe=e.vis?pos(e):anchor;
        if(e.vis && (foe-anchor).len()>1850 && e.st==S_FREE){anchorUntil=-1;return;}
        V targetPos=e.vis?foe*.40+anchor*.60:anchor;
        if(e.vis && e.st==S_STUN)targetPos=foe;
        double gap=(targetPos-me).len();
        bool visible=los(me,targetPos);
        if(!visible || gap>8800)return;
        int age=t-siegeLaunch;
        bool postBlock=contact==EnemyParry && t-contactFrame<=cf.slash_post+1 && contactFrame>=siegeLaunch;
        if(siegeDash>=siegeLaunch && t-siegeDash<=cf.dash_pre+cf.dash_t+1 && p.st==S_DASH){
            if(p.timer<=cf.dash_post || p.timer>cf.dash_post+cf.dash_t)return;
            Body stop{p.x,p.y,p.vx,p.vy};bool safe=true;
            int pre=d.st==D_HAND?cf.slash_pre:cf.kick_pre;
            for(int z=0;z<pre;z++){move(stop,{});if(cell(pos(stop),z+2)==C_PIT)safe=false;}
            V strike=(postBlock?foe:targetPos)-pos(stop);
            if(safe && strike.len()<reach-130 && los(pos(stop),pos(stop)+strike) &&
               (d.st==D_HAND || e.st!=S_STUN)){
                a=command({},A_MELEE,strike.unit());return;
            }
            // Stay on course for the pickup. An empty swing ends the dash
            // before its first travel step and leaves the dart on the ground.
            a={};return;
        }
        if(age>0 && age<17 && d.st!=D_HAND && (p.st==S_FREE || p.st==S_THROW || p.st==S_THROWN)){
            V mark=d.st==D_GROUND?pos(d):targetPos-(targetPos-me).unit()*900;
            V pursuit=(targetPos-me).unit();
            if(d.st==D_GROUND)pursuit=((mark-me).unit()*1.5+(targetPos-me).unit()).unit();
            if(p.st==S_FREE && p.cd==0 && gap>1500 && gap<5220 &&
                postBlock && (mark-me).len()<4050){
                // Several rays can pass within pickup radius of the same
                // grounded dart. Prefer one that also leaves a safe slash,
                // including the residual travel when the dash is cancelled.
                V axis=(targetPos-me).unit(),side=axis.side();
                double high=-1e30;V bestRay;
                for(int z=-8;z<=8;z++){
                    V ray=(pursuit+side*(z*.075)).unit();Body b{p.x,p.y,p.vx,p.vy};
                    bool armed=false,valid=true;
                    for(int h=1;h<=cf.dash_pre+cf.dash_t;h++){
                        bool fly=h>cf.dash_pre;
                        if(fly){
                            Body stop=b;bool land=true;int wind=cf.slash_pre;
                            for(int j=0;j<wind;j++){
                                move(stop,{});if(cell(pos(stop),h+j+2)==C_PIT)land=false;
                            }
                            double dist=(pos(stop)-foe).len();
                            if(armed && land && valid && dist<reach-70 && los(pos(stop),foe)){
                                double value=3000.-155*h-.23*dist-50*std::abs(z);
                                if(value>high){high=value;bestRay=ray;}
                            }
                        }
                        move(b,fly?ray*cf.dash_v:V{},fly);
                        armed|=(pos(b)-mark).len()<cf.pick_r-16;
                        bool landing=!fly || h==cf.dash_pre+cf.dash_t;
                        if(landing && cell(pos(b),h+3)==C_PIT)valid=false;
                        if(h==cf.dash_pre+cf.dash_t && valid && armed && los(pos(b),foe)){
                            double value=1000.-.6*(pos(b)-foe).len()-35*std::abs(z);
                            if(value>high){high=value;bestRay=ray;}
                        }
                    }
                }
                if(high>0){siegeDash=t;a=command({},A_DASH,bestRay);return;}
                Body b{p.x,p.y,p.vx,p.vy};bool safe=true;
                for(int h=1;h<=cf.dash_pre+cf.dash_t;h++){
                    bool fly=h>cf.dash_pre;move(b,fly?pursuit*cf.dash_v:V{},fly);
                    if((!fly || h==cf.dash_pre+cf.dash_t) && cell(pos(b),h+3)==C_PIT)safe=false;
                }
                if(safe){siegeDash=t;a=command({},A_DASH,pursuit);return;}
            }
            if((postBlock || d.st==D_OUT) && shortWalk(p,pursuit,3,cf.run_v*.5)){
                a=command(pursuit);return;
            }
        }
        if(p.st!=S_FREE || d.st!=D_HAND || !e.vis)return;
        if(e.st==S_STUN || his.st!=D_HAND || e.st==S_THROW)return;
        if(e.st!=S_FREE && e.st!=S_SLASHED)return;
        V axis=(targetPos-me).unit(),side=axis.side();
        if(gap<reach+180)return;
        double limit=5100;
        if(gap>limit || t-siegeLaunch<16){
            if(a.act==A_MELEE && gap<2600)return;
            double best=-1e30;V choice;
            for(int sign:{1,-1})for(double turn:{.28,.65,1.2,2.5}){
                V m=(axis+side*(sign*turn)).unit();
                if(!shortWalk(p,m,6,cf.run_v))continue;
                Body b{p.x,p.y,p.vx,p.vy};
                for(int z=0;z<5;z++)move(b,m*cf.run_v);
                int tile=index(pos(b));if(tile<0)continue;
                V previous=pos(history[std::max<int>(0,t-cf.delay)%HISTORY]);
                double quality=-std::abs((pos(b)-targetPos).len()-(limit-350))*.86
                    +.38*std::min(1150.,std::abs((pos(b)-previous).dot(side)))
                    +70*std::min(4,border[tile])+90*(sign==sideSign)-.12*(home-pos(b)).len();
                if(quality>best){best=quality;choice=m;}
            }
            if(best>-1e25)a=command(choice);
            return;
        }
        if(e.st==S_SLASHED && e.timer<=cf.delay && gap>3900)return;
        V m=axis,ray=(targetPos-me).unit();Body b{p.x,p.y,p.vx,p.vy};
        if(!shortWalk(p,m,cf.throw_pre+cf.throw_post,cf.run_v*.5))return;
        for(int z=0;z<cf.throw_pre;z++)move(b,m*(cf.run_v*cf.throw_move*.01));
        ray=(targetPos-pos(b)).unit();
        if(!los(pos(b),targetPos-ray*220))return;
        siegeLaunch=t;sideSign=-sideSign;a=command(m,A_THROW,ray);
    }
    // Reconstruct a visible attack's recovery and compare the remaining
    // movement envelope to the projectile's width at first contact.
    void punishRecovery(const Obs &o,Action &a){
        if(t>contestUntil+35 || contestUntil<0 || duelEnemy<0 || target<0 ||
           !o.p[target].vis || o.me().st!=S_FREE || o.my_dart().st!=D_HAND)return;
        const auto &e=o.p[target];const auto &p=o.me();
        bool locked=e.st==S_SLASHED || e.st==S_SLASH || e.st==S_STUN;
        if(!locked || o.d[target].st!=D_HAND || e.timer<=0)return;
        int old=std::min<int>(cf.delay,t),stop=e.timer+(e.st==S_SLASH?cf.slash_post:0);
        if(stop<old-1)return;
        V q=pos(e);if((q-me).len()>5500 || !los(me,q))return;
        Body enemy{e.x,e.y,e.vx,e.vy};
        for(int i=0;i<std::min(old+int(cf.throw_pre)+4,stop);i++){
            if(e.st==S_STUN){V push{double(enemy.vx),double(enemy.vy)};move(enemy,push,true);
                enemy.vx=rdiv(enemy.vx*cf.kick_keep,1000);enemy.vy=rdiv(enemy.vy*cf.kick_keep,1000);}
            else move(enemy,{});
        }
        q=pos(enemy);V axis=(q-me).unit();V chosen,ray;double best=.04;
        int timeleft=stop-old;
        for(V dir:{axis,axis.side(),axis.side()*(-1.),(axis.side()-axis*.6).unit(),(axis.side()*(-1.)-axis*.6).unit(),axis*(-1.),V{}}){
            Body b{p.x,p.y,p.vx,p.vy};bool safe=true;V origin;
            for(int h=1;h<=cf.throw_pre+cf.throw_post;h++){
                move(b,dir*(cf.run_v*cf.throw_move*.01));if(cell(pos(b),h+2)==C_PIT)safe=false;
                if(h==cf.throw_pre)origin=pos(b);
            }
            if(!safe || !los(origin,q))continue;
            V aim=(q-origin).unit();double dist=(q-origin).len(),travel=0;
            for(int h=cf.throw_pre+1;h<=std::min<int>(H,cf.throw_pre+8);h++){
                travel+=std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);
                if(travel+radius-60<dist)continue;
                double freedom=std::max(0,h-timeleft)*cf.run_v;
                double delayToParry=std::max<int>(cf.delay+cf.slash_pre,timeleft+cf.slash_pre);
                double value=1.-freedom/1650.-std::max(0.,h-delayToParry)*.32-
                    std::max(0.,1250.-(pos(b)-q).len())*.0005;
                int observed=std::max(0,t-int(cf.delay)+std::min(0,timeleft));
                const auto &prior=history[observed%HISTORY];
                V normal=(pos(prior)-q).unit().side();
                Body after=b;bool stable=true;
                for(int z=0;z<4;z++){move(after,dir*cf.run_v);if(cell(pos(after),z+6)==C_PIT)stable=false;}
                if(!stable)break;
                double delta=(pos(after)-pos(prior)).dot(normal);
                double free=std::min(std::abs(delta),std::abs(delta-vel(prior).dot(normal)*5.));
                double survival=clip(free/(radius*1.6),0.,1.);
                double chance=value;
                value+=0.32*survival;
                if(value>best && chance>0.21){best=value;chosen=dir;ray=aim;}
                break;
            }
        }
        if(best>.04){a=command(chosen,A_THROW,ray);launch=t;launchMove=chosen;}
    }
