"/Vra/bldvBjTBzlBAA5lBAAncAAvKAA/CAA1CpFpFzKnP/O5ZjepjB/xB9xBvvBluBrtB7oB/KtblRvd3PtW3J7HvB5DF5BAAtFpGrFvOxOvQ/PtRtSpXrbrgB7c1d/d";
    static constexpr short fanRoots[]={0,271,536,769,1044,1307,1574,1843,};
    static constexpr int FAN=28;
    // Include early braking, a full landing, and the first steps after
    // landing. A cone around the current aim alone can miss an entire branch.
    void dashRays(const Obs &o,V from,V ray,V side,double gap,V directions[FAN])const{
        auto &e=o.p[duelEnemy];V foe=pos(e),axis{e.ax*.001,e.ay*.001};
        int j=0;directions[j++]=ray;
        for(double offset:{320.,675.,1080.,1500.,2025.,2780.})
            for(double sign:{1.,-1.})directions[j++]=(ray*gap+side*(sign*offset)).unit();
        Body run{e.x,e.y,e.vx,e.vy};
        for(int travel=0;travel<=4;travel++){
            Body stop=run;
            for(int h=0;h<2;h++)move(stop,{});
            V place=pos(stop),ground=pos(o.d[duelEnemy]);
            V look=pos(history[(t-cf.delay)%HISTORY])-place;
            V follow=ground-place;
            for(V dir:{V{},look.unit(),follow.unit()}){
                Body walk=stop;
                if(dir.len()>.4)for(int h=0;h<3;h++){
                    Body next=walk;move(next,dir*cf.run_v);
                    if(cell(pos(next),h+3)==C_PIT)break;
                    walk=next;
                }
                directions[j++]=(pos(walk)-from).unit();
            }
            move(run,axis*cf.dash_v,true);
        }
    }
    template<class Node,size_t Nodes,size_t Leaves,size_t Roots>
    static int correctedRay(const Node (&tree)[Nodes],const short (&leaf)[Leaves][17],
                            const short (&roots)[Roots],const double features[],double margin){
        double chance[17]{};
        for(int j:roots){
            while(tree[j].f>=0){
                const auto &p=tree[j];
                j=features[p.f]<=p.cut?p.l:p.r;
            }
            for(int z=0;z<17;z++)chance[z]+=leaf[tree[j].l][z]/double(Roots);
        }
        int best=8;double high=chance[8]+margin;
        for(int z=0;z<17;z++){
            double score=chance[z]-4*std::abs(z-8);
            if(score>high){best=z;high=score;}
        }
        return best;
    }
    // Compare the current ray to sixteen corrections using the motion before
    // release, the attacker's delayed observations and the walls at landing.
    // Relative geometry at release plus observed choices on previous dashes.
    // Quantities are in world units, ticks, or normalized direction cosines.
    static constexpr int SHOT_INPUTS=36,SHOT_RAYS=9;
    // Measure the displacement AFTER a previous dash. Two dashes with the
    // same launch velocity can end in very different pickup or attack routes.
    struct DashHistory {
        int start=-1000,sampled=-1000,weapon=D_HAND,count=0,hadSwing=0,hadCast=0;
        V origin{},axis{},side{},landing{},mark{},opponent{};
        double along=0,cross=0,nearer=0,pickup=0,swing=0,cast=0,coast=0;
    } recentDash;
    void watchLanding(const Obs &o){
        int k=duelEnemy;if(k<0 || t<cf.delay || !o.p[k].vis || !info().M().nwave)return;
        const auto &e=o.p[k];const auto &d=o.d[k];int frame=t-cf.delay;auto &v=recentDash;
        if(e.st==S_DASH && e.timer==cf.dash_pre+cf.dash_t+cf.dash_post-1 && frame!=v.start){
            v.start=frame;v.origin=pos(e);v.axis=V{double(e.ax),double(e.ay)}.unit();v.side=v.axis.side();
            v.opponent=pos(history[frame%HISTORY]);if((v.opponent-v.origin).dot(v.side)<0)v.side=v.side*(-1.);
            Body b{e.x,e.y,e.vx,e.vy};for(int i=0;i<cf.dash_t;i++)move(b,v.axis*cf.dash_v,true);
            v.landing=pos(b);v.mark=pos(d);v.weapon=d.st;v.hadCast=v.hadSwing=0;
        }
        int elapsed=frame-v.start;const int at=cf.dash_pre+cf.dash_t+cf.dash_post+3;
        if(elapsed<0 || elapsed>at+1 || v.start==v.sampled)return;
        if(e.st==S_THROW || e.st==S_THROWN)v.hadCast=1;
        if(e.st==S_SLASH || e.st==S_KICK || e.st==S_SLASHED || e.st==S_KICKED)v.hadSwing=1;
        if(elapsed<at)return;
        v.sampled=v.start;double weight=v.count?0.42:1.;v.count++;
        auto note=[&](double &mean,double x){mean+=weight*(x-mean);};V extra=pos(e)-v.landing;
        note(v.along,extra.dot(v.axis));note(v.cross,extra.dot(v.side));
        note(v.nearer,(v.opponent-v.landing).len()-(v.opponent-pos(e)).len());
        note(v.pickup,v.weapon!=D_HAND && d.st==D_HAND?1000.:0.);
        note(v.swing,1000*v.hadSwing);note(v.cast,1000*v.hadCast);note(v.coast,vel(e).dot(v.axis));
    }
    int dashMarker=-1000,priorDash=-1000,fastRepeats=0,freeTraversals=0;
    int travelled=0,finishedRuns=0,cancelledRuns=0;
    V dashOrigin;bool observedTravel=false,armedTravel=false;
    void recordTraversal(const Obs &o){
        if(n==2)watchLanding(o);
        int k=duelEnemy;if(k<0 || !info().M().nwave || (n!=2 && cf.mode!=1))return;
        const auto &p=o.p[k];if(!p.vis || t<cf.delay)return;
        int stamp=t-cf.delay;
        if(p.st==S_DASH && stamp>dashMarker && p.timer==cf.dash_pre+cf.dash_t+cf.dash_post-1){
            priorDash=dashMarker;dashMarker=stamp;dashOrigin=pos(p);
            if(stamp-priorDash<=cf.dash_cd+cf.dash_t+cf.dash_pre+8)fastRepeats++;
            const auto &seen=history[std::max(0,stamp-1-int(cf.delay))%HISTORY];
            V dir=V{double(p.ax),double(p.ay)}.unit();
            V land=pos(p)+dir*(cf.dash_t*cf.dash_v);
            double closest=swept(pos(p)-pos(seen),land-pos(seen)-vel(seen)*4.);
            observedTravel=closest>reach+cf.body_r+2*cf.run_v;
            if(observedTravel){freeTraversals++;if(o.d[k].st==D_HAND)armedTravel=true;}
        }
        if(stamp>dashMarker && stamp<=dashMarker+cf.dash_pre+cf.dash_t+cf.dash_post+1 && p.st!=S_DASH && travelled!=dashMarker){
            travelled=dashMarker;
            if(p.st==S_SLASH || p.st==S_SLASHED || p.st==S_KICK || p.st==S_KICKED)cancelledRuns++;
            else if((pos(p)-dashOrigin).len()>.8*cf.dash_v*cf.dash_t)finishedRuns++;
        }
    }
    void compareLines(const Obs &o,V from,V original,V corrected,double gap,V (&lines)[SHOT_RAYS],double (&x)[SHOT_INPUTS]){
        int k=duelEnemy;const auto &e=o.p[k];const auto &d=o.d[k];V foe=pos(e),dir=V{double(e.ax),double(e.ay)}.unit();
        V land=foe;int rem=e.st==S_DASH?std::max<i64>(0,std::min<i64>(cf.dash_t,e.timer-cf.dash_post)):0;
        Body b{e.x,e.y,e.vx,e.vy};for(int h=0;h<rem;h++){move(b,dir*cf.dash_v,true);land=pos(b);}
        double horizon=std::max(0.,std::min(7.,cf.delay+cf.throw_pre+gap/(cf.dart_v*.85)-rem));
        lines[0]=original;lines[1]=corrected;lines[2]=(original+corrected).unit();lines[3]=(land-from).unit();
        V toDart=(pos(d)-land).unit(),toUs=(from-land).unit();
        V walk=vel(e).unit();if(e.st==S_DASH)walk=dir;
        int j=4;for(V v:{walk,toDart,toUs,toUs.side(),toUs.side()*-1.}){
            Body next{std::lround(land.x),std::lround(land.y),0,0};
            for(int h=0;h<std::lround(horizon);h++){
                Body g=next;move(g,v*cf.run_v);if(cell(pos(g),cf.throw_pre+h)==C_PIT)break;next=g;
            }
            lines[j++]=(pos(next)-from).unit();
        }
        double length=(land-from).len(),dd=(pos(d)-land).len();V side=original.side();
        int f=0;auto add=[&](double v){x[f++]=v;};
        add(e.st);add(e.timer);add(d.st);add(gap);add(rem);add(length);add(dd);
        add((pos(d)-foe).len());add((foe-from).dot(dir));add(std::abs((foe-from).dot(dir.side())));
        add((pos(d)-land).dot(dir));add(std::abs((pos(d)-land).dot(dir.side())));add(vel(e).len());
        add(std::abs((land-from).dot(side)));add((corrected-original).len()*gap);
        add(std::min(4,fastRepeats));add(std::min(6,freeTraversals));add(std::min(4,finishedRuns));add(std::min(4,cancelledRuns));
        add(priorDash<0?120:std::min(120,dashMarker-priorDash));add(observedTravel);add(armedTravel);
        add(std::min<int>(120,t-cf.delay-dashMarker));add(1000*dir.dot(toDart));add(1000*dir.dot(toUs));
        add(cell(land));add(cell(land+dir*750.));add(cell(land+toUs*750.));add(cell(land+toDart*750.));
        for(int z:{0,1,3})add(std::abs((land-from).dot(lines[z].side())));
        add(std::abs((pos(d)-from).dot(original.side())));add(std::abs((pos(d)-from).dot(corrected.side())));
        add(cell(land+dir*1500));add(1000*walk.dot(toUs));
    }
