    static constexpr int outcomeRoots[]={0,15,30,43,58,73,86,101,116,129,144,159,172,187,202,215,230,245,260,273,286,299,312,325,338,353,366,381,396,409,424,439,454,469,484,495,508,523,538,551,564,577,590,605};
    static constexpr double baseOutcome=0.4343140816079428;
    double groundAccuracy(const Obs &o,int k,const Action &a){
        const auto &p=o.p[k];V diff=pos(p)-me,axis=diff.unit();
        V velocity=vel(p),dashDir=V{double(p.ax),double(p.ay)}.unit();
        V ray=V{double(a.ax),double(a.ay)}.unit(),side=ray.side();
        V dart=pos(o.d[k]),toDart=dart-pos(p);int stamp=std::max<int>(0,t-cf.delay);
        const auto &past=trail[k][std::max(0,stamp-4)%TRAIL];
        V flow=past.frame==stamp-4?(pos(p)-past.p)*.25:velocity;
        if(velocity.dot(side)<0)side=side*(-1.);
        double f[21]={diff.len(),double(p.st),double(p.timer),double(p.cd),double(o.d[k].st),velocity.len(),
            axis.dot(velocity),velocity.dot(side),axis.dot(flow),flow.dot(side),toDart.len(),(dart-me).len(),
            toDart.unit().dot(axis),toDart.unit().dot(side),diff.dot(side),dashDir.dot(axis),dashDir.dot(side)};
        int at=17;
        for(int h:{4,8}){
            V dest=diff+velocity*h;
            if(p.st==S_DASH){
                int flight=std::max<i64>(0,std::min(cf.dash_t,p.timer-cf.dash_post));
                int pre=std::max<i64>(0,p.timer-cf.dash_post-cf.dash_t);
                dest=diff+dashDir*(cf.dash_v*std::max(0,std::min(h-pre,flight)));
            }
            f[at++]=dest.len();f[at++]=dest.dot(side);
        }
        double q=baseOutcome;
        for(int root:outcomeRoots){
            int j=root;while(outcomeTree[j].feature>=0){const auto &v=outcomeTree[j];j=f[v.feature]<v.value?v.left:v.right;}
            q+=outcomeTree[j].value;
        }return q;
    }
    // Extrapolate each observed movement to impact, then test the whole flight.
    // The last two trajectories describe an approach that brakes or keeps closing.
    bool finishLoose(const Obs &o,int k,V walk,Action &a){
        const Player &p=o.me(),&foe=o.p[k];const Actor &e=actor[k];const Dart &d=o.d[k];
        double gap=(e.path[0][0]-me).len();if(gap>3890 ||
            (gap>3220 && a.act!=A_THROW && foe.st!=S_RECALL && foe.st!=S_DASH))return false;
        Body b{p.x,p.y,p.vx,p.vy};for(int i=0;i<cf.throw_pre;i++)move(b,walk*(cf.run_v*cf.throw_move*.01));
        V origin=pos(b),old=V{double(a.ax),double(a.ay)}.unit();bool planned=a.act==A_THROW;
        if(!shortWalk(p,walk,cf.throw_pre+cf.throw_post,cf.run_v*.60))return false;
        double best=-1,reference=0;V aim;int end=std::min<int>(H,cf.delay+2);
        for(int m=-1;m<NMODEL;m++){
            V ray=m<0?old:(e.path[m][std::min(end,5)]-origin).unit();if(ray.len()<.9)continue;
            V start=origin;double votes[NMODEL]{};for(int h=cf.throw_pre+1;h<=end;h++){
                V stop=start+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);i64 x,y;
                bool wall=seg_wall(live,std::lround(start.x),std::lround(start.y),std::lround(stop.x),std::lround(stop.y),x,y);if(wall)stop={double(x),double(y)};
                for(int j=0;j<NMODEL;j++){
                    double err=swept(start-e.path[j][h-1],stop-e.path[j][h]);double dodge=cf.run_v*std::max<i64>(0,h-cf.delay-1);
                    votes[j]=std::max(votes[j],clip((radius-err-dodge)/300.,0,1));
                }start=stop;if(wall)break;
            }
            double score=0;for(int j=0;j<NMODEL;j++)score+=e.weight[j]*votes[j];
            if(m<0)reference=score;if(score>best){best=score;aim=ray;}
        }
        if(best<(planned?.72:.91) || (planned && best<reference+.19))return false;
        Action shot=command(walk,A_THROW,aim);if(groundAccuracy(o,k,shot)<(planned?.48:.72))return false;
        if(!planned && !((d.st==D_RISE && foe.timer>=cf.delay+cf.throw_pre+2) || foe.st==S_DASH && foe.timer>cf.dash_post || gap<2680))return false;
        a=shot;return true;
    }
    void contestDart(const Obs &o,Action &a){
        const int k=duelEnemy;
        if(n!=2 || k<0 || !info().M().nwave || !actor[k].valid || o.my_dart().st!=D_HAND || t<cf.delay)return;
        // A stationary rival who has already yielded several shooting opportunities
        // can be attacked on their own ground, especially from a prepared line.
        if(quietPressure>=8 && openOffers>=12 && (home-actor[k].oldpos).len()+420<(home-me).len())return;
        if(initialRefuge[k] && startLead[k]>1100 && (slowEvidence>=t-45 || patientSteps>2 || t<postLease+30) &&
           (home-actor[k].oldpos).len()+700<(home-me).len())return;
        if(t-siegeLaunch<=18 || t<=anchorUntil || (occupied && t<=waitingUntil+2))return;
        if(!o.p[k].vis){
            const int state=o.d[k].st;const Actor &track=actor[k];
            if(a.act==A_THROW && o.me().st==S_FREE && (state==D_GROUND || state==D_RISE || state==D_CALL)){
                // Delayed sight ends at the grass edge. A known grounded dart
                // alone does not pinpoint the player hiding beyond it.
                double mean=0;for(int m=0;m<NMODEL;m++)mean+=track.weight[m]*(track.path[m][3]-me).len();
                if(mean>3440 && (grass[k].span>cf.body_r || mean>3980))a=command(V{a.mx*.001,a.my*.001});
            }
            return;
        }
        const auto &p=o.me(),&other=o.p[k];const auto &d=o.d[k];const auto &e=actor[k];
        if(d.st!=D_GROUND && d.st!=D_RISE)return;
        V walk={a.mx*.001,a.my*.001};V foe=e.path[0][0];double distance=(me-foe).len();
        if(p.st!=S_FREE || other.st==S_STUN || (d.st!=D_GROUND && d.st!=D_RISE) || distance>8800)return;
        if(a.act!=A_THROW && a.act!=A_NONE)return;
        double mark=(pos(d)-me).len(),pickup=(pos(d)-foe).len();
        double projected=0;for(int j=0;j<NMODEL;j++)projected+=e.weight[j]*(e.path[j][3]-me).len();
        if(finishLoose(o,k,walk,a))return;
        bool withheld=false;
        if(a.act==A_THROW){
            double q=groundAccuracy(o,k,a);
            double far=std::max(distance*.65+projected*.35,(pos(other)-me).len()*.55+distance*.45);
            double required=clip((far-2850.)/1750.,0,1)*0.68;
            if(d.st==D_RISE || pickup<900)required*=.68;
            if(far<3100 || q>=required)return;
            a=command(walk);withheld=true;
        }
        if(a.act!=A_NONE)return;
        if(withheld && mark>1800 && d.st==D_GROUND && distance>3800 && pickup>1400){
            V dir=(foe-me).unit();if(los(me,foe) && shortWalk(p,dir,4,cf.run_v))a=command(dir);
        }
    }
    int shortRelease=-1000;
    // All distances below are in millimetres, times in simulation ticks.
    // Resolve a close contest before a new reaction to this particular release.
    // Include continued lateral running around the observer, straight movement,
    // a brake and a turn. Collision checks use the same wall and body movement.
    bool afterShotRoute(const Player &p,V walk,V ray,V foe){
        if(p.cd>cf.throw_pre+cf.throw_post || ray.len()<.9)return false;
        Body b{p.x,p.y,p.vx,p.vy};for(int i=0;i<cf.throw_pre+cf.throw_post;i++)move(b,walk*(cf.run_v*cf.throw_move*.01));
        V from=pos(b);double along=(foe-from).dot(ray);
        if(along<850 || along>4500 || std::abs((foe-from).dot(ray.side()))>cf.slash_reach)return false;
        // A parry leaves the dart up to one slash reach in front of its owner.
        // Two likely drop positions and a kick window must lie on safe ground.
        V first=from+ray*std::max(400.,along-1200.),last=from+ray*std::max(400.,along-520.);
        bool early=false,late=false,kick=false;int h=cf.throw_pre+cf.throw_post;
        for(int i=0;i<cf.dash_pre;i++){move(b,{});h++;if(cell(pos(b),h+3)==C_PIT)return false;}
        for(int i=0;i<cf.dash_t;i++){
            V prev=pos(b);move(b,ray*cf.dash_v,true);h++;int id=index(pos(b));if(id<0 || jumpLatest[id]<=t+h+8)return false;
            early|=swept(prev-first,pos(b)-first)<cf.pick_r;late|=swept(prev-last,pos(b)-last)<cf.pick_r;
            kick|=(pos(b)-foe).len()<cf.kick_reach-100 && los(pos(b),foe);
        }
        return early && (late || kick);
    }
    void insideReach(const Obs &o,Action &a){
        int k=duelEnemy;if(n!=2 || k<0 || !info().M().nwave || !o.p[k].vis || !actor[k].valid ||
            o.my_dart().st!=D_HAND || o.d[k].st!=D_HAND || o.p[k].st!=S_FREE || o.me().st!=S_FREE)return;
        const auto &p=o.me(),&e=o.p[k];int delay=std::min<int>(t,cf.delay),stamp=t-delay;
        V foe=pos(e),v=vel(e),oldSelf=pos(history[stamp%HISTORY]),to=(oldSelf-foe).unit();
        double gap=(foe-me).len(),speed=v.len(),r=std::max(800.,(oldSelf-foe).len());
        double inward=v.dot(to),lateral=v.dot(to.side());
        // A stale near forecast can put a runner inside the release window a
        // full metre before contact. Preserve the existing long-line aim there.
        int unreacted=std::max(1,int(cf.delay-cf.throw_pre+1));
        double quickRange=radius+unreacted*cf.dart_v-cf.dart_dec*unreacted*(unreacted-1)*.5;
        if(gap>quickRange && a.act!=A_MELEE)return;
        if(gap>4900 || (t<=anchorUntil && gap>2600) || t==interceptFire || t<=sweepUntil || t<=counterUntil)return;
        int driven=0,lateralSteps=0;double gained=0;
        for(int z=0;z<=12 && z<=stamp;z++){
            const auto &u=trail[k][(stamp-z)%TRAIL];if(u.frame!=stamp-z || u.dart!=D_HAND || u.state!=S_FREE)continue;
            V delta=u.observer-u.p;double radial=u.v.dot(delta.unit());
            if(radial>cf.run_v*.32 && delta.len()<5900)driven++;
            if(std::abs(u.v.dot(delta.unit().side()))>cf.run_v*.68 && delta.len()<3400)lateralSteps++;
            gained+=radial;
        }
        bool contactStart=stamp<=7 && (pos(history[0])-pos(o.p[k])).len()<3450;
        bool pursuit=driven>=4 && gained>cf.run_v*1.5 || lateralSteps>=3 && driven>=1;
        if(!contactStart && (!pursuit || occupied || t<=anchorUntil+5 || t-siegeLaunch<=18 || t<=waitingUntil+1))return;
        // Attribute closing speed to the player who produced it. A runner
        // catching a retreat and a defender approached by us pose different risks.
        double movedByUs=0,movedByThem=0;int orbiting=0,freeSamples=0;
        for(int z=0;z<16 && z<stamp;z++){
            const auto &u=trail[k][(stamp-z)%TRAIL];if(u.frame!=stamp-z || u.state!=S_FREE || u.dart!=D_HAND)continue;
            V dir=(u.observer-u.p).unit();movedByUs-=vel(history[(stamp-z)%HISTORY]).dot(dir);
            movedByThem+=u.v.dot(dir);freeSamples++;
            if(std::abs(u.v.dot(dir.side()))>cf.run_v*.72 && (u.observer-u.p).len()<3100)orbiting++;
        }
        bool pushed=freeSamples>=5 && movedByThem>std::max(530.,movedByUs+420.) && movedByThem>cf.run_v*freeSamples*.28;
        bool circled=orbiting>=4 && movedByUs<cf.run_v*freeSamples*.10 && movedByThem>-200;
        if(!contactStart && (!pushed && !circled || t<postLease+30 || enemyShotCount[k]>0 && movedByThem<cf.run_v*freeSamples*.62))return;
        bool sideRun=std::abs(lateral)>.48*cf.run_v && std::abs(lateral)>.64*std::abs(inward);
        bool uncertain=speed<cf.run_v*.20 && stamp==0;
        if(gap>3350 && !sideRun && !uncertain)return;
        if(gap>3220 && a.act!=A_MELEE && (actor[k].path[0][0]-me).len()>3300)return;
        if(speed>35 && speed<cf.run_v*.72 && !sideRun && gap>2550)return;
        V walk{a.mx*.001,a.my*.001};Body stop{p.x,p.y,p.vx,p.vy};
        for(int h=0;h<cf.slash_pre;h++)move(stop,{});
        constexpr int M=9,L=9;V path[M][L+1];double weights[M]{};
        double sign=lateral>=0?1.:-1.;V center=oldSelf;
        for(int j=0;j<M;j++){
            Body b{e.x,e.y,e.vx,e.vy};
            for(int h=-delay;h<=L;h++){
                if(h>=0)path[j][h]=pos(b);
                V ref=center;
                if(h+delay>1){int seen=std::max(0,std::min(t,t+h-int(cf.delay)));ref=pos(history[seen%HISTORY]);}
                V axis=(ref-pos(b)).unit();double radial=0.;V desired=v;
                if(j==1 || j==2 || j==3 || j==4){
                    double targetR=j==2?std::min(r,1650.):j==3?std::min(r,2350.):r;
                    radial=clip(((ref-pos(b)).len()-targetR)*.32+inward*.45,-cf.run_v*.8,cf.run_v*.90);
                    double lateralSpeed=std::sqrt(std::max(0.,double(cf.run_v*cf.run_v)-radial*radial));
                    desired=axis*radial+axis.side()*(lateralSpeed*sign*(j==4?-1.:1.));
                }else if(j==5)desired={};
                else if(j==6)desired=axis*cf.run_v;
                else if(j==7 || j==8){double turn=(j==7?1.:-1.)*.105*(h+delay);desired=v*std::cos(turn)+v.side()*std::sin(turn);}
                move(b,desired);
            }
        }
        if(uncertain){double w[M]={.04,.17,.06,.06,.31,.04,.22,.05,.05};std::copy(w,w+M,weights);}
        else if(sideRun){double w[M]={.17,.21,.20,.10,.045,.04,.035,.10,.10};std::copy(w,w+M,weights);}
        else {double w[M]={.21,.055,.10,.055,.04,.15,.22,.085,.085};std::copy(w,w+M,weights);}
        double best=0,early=0;V bestRay,bestWalk=walk;
        double swing=0;V face=V{double(a.ax),double(a.ay)}.unit();int sh=std::min<int>(cf.slash_pre,L);
        for(int j=0;j<M;j++){
            V line=path[j][sh]-pos(stop);
            if(line.len()<=reach && (line.len()<=cf.body_r || face.dot(line.unit())>=cf.slash_cos*.001) && los(pos(stop),path[j][sh]))swing+=weights[j];
        }
        if(a.act==A_MELEE && swing>.52)return;
        bool incoming=false;for(int h=1;h<=cf.slash_pre+1 && h<=H;h++)for(auto &f:flights[h])
            if(f.confidence>.36 && swept(f.a-me,f.b-me)<reach+120)incoming=true;
        if(a.act==A_MELEE && !incoming && swing<.23)a=command(walk);
        if(a.act==A_MELEE || gap>4050 || !shortWalk(p,walk,cf.throw_pre+cf.throw_post,cf.run_v*.5))return;
        V toward=(foe-me).unit();
        for(V step:{toward,walk}){
        if(!shortWalk(p,step,cf.throw_pre+cf.throw_post,cf.run_v*.60))continue;
        Body launch{p.x,p.y,p.vx,p.vy};for(int h=0;h<cf.throw_pre;h++)move(launch,step*(cf.run_v*cf.throw_move*.01));
        V start=pos(launch),axis=(foe-start).unit(),side=axis.side();
        for(int z=-16;z<=16+M;z++){
            double angle=z*.063;V ray= z<=16?axis*std::cos(angle)+side*std::sin(angle):(path[z-17][5]-start).unit();
            V begin=start;double hits[M]{},quick[M]{};
            for(int h=cf.throw_pre+1;h<=std::min<i64>(L,cf.delay+3);h++){
                V end=begin+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);
                i64 x,y;bool wall=seg_wall(live,std::lround(begin.x),std::lround(begin.y),std::lround(end.x),std::lround(end.y),x,y);
                if(wall)end={double(x),double(y)};
                for(int j=0;j<M;j++){
                    double miss=swept(begin-path[j][h-1],end-path[j][h]);
                    double evade=cf.run_v*std::max<i64>(0,h-cf.delay-1);
                    hits[j]=std::max(hits[j],clip((radius+70-miss-evade*.30)/240.,0,1));
                    quick[j]=std::max(quick[j],clip((radius+40-miss-evade)/240.,0,1));
                }
                begin=end;if(wall)break;
            }
            double h=0,q=0;for(int j=0;j<M;j++){h+=weights[j]*hits[j];q+=weights[j]*quick[j];}
            double score=.25*h+.75*q;if(score>best){best=score;bestRay=ray;early=q;bestWalk=step;}
        }
        }
        bool follow=afterShotRoute(p,bestWalk,bestRay,foe);
        if(best>(follow?0.37:0.47) && early>0.32){a=command(bestWalk,A_THROW,bestRay);shortRelease=t;return;}
        if(uncertain && a.act==A_NONE && gap>2100 && gap<3200){
            V step=((foe-me).unit()*.58+walk*.47).unit();
            if(shortWalk(p,step,3,cf.run_v))a=command(step);
        }
    }
    // Preserve the follow-up after a close throw. A dash through a free armed
    // opponent gives them a whole slash window if the outbound shot misses.
    void afterRelease(const Obs &o,Action &a){
        int k=duelEnemy;if(n!=2 || k<0 || t>shortRelease+24 || t<=shortRelease || !o.p[k].vis || !actor[k].valid ||
            o.my_dart().st==D_HAND || o.d[k].st!=D_HAND || o.p[k].st!=S_FREE || o.me().st!=S_FREE)return;
        const auto &p=o.me();const auto &d=o.my_dart();const Actor &e=actor[k];V foe=e.path[0][0],to=foe-me;
        double gap=to.len(),mark=(pos(d)-me).len();if(gap>4500 || (d.st==D_GROUND && mark<cf.pick_r+cf.run_v))return;
        V old=V{a.mx*.001,a.my*.001};bool dash=a.act==A_DASH;
        if(a.act==A_MELEE && gap<cf.kick_reach-100)return;
        if(dash){V ray=V{a.ax*.001,a.ay*.001}.unit();if(ray.dot(to.unit())<.38)return;
            V end=me+ray*(cf.dash_v*cf.dash_t);if(d.st==D_GROUND && (end-pos(d)).len()<cf.pick_r && (end-foe).len()>1900)return;
        }else if(gap>2900 || old.dot(to.unit())<-.18)return;
        V retreat=to.unit()*(-1.),side=retreat.side();double best=-1e20;V escape;
        for(int z=-4;z<=4;z++){
            V dir=retreat*std::cos(z*.39)+side*std::sin(z*.39);Body b{p.x,p.y,p.vx,p.vy};
            double near=10000,clearance=0;bool safe=true;
            for(int h=1;h<=6;h++){
                move(b,dir*cf.run_v);int id=index(pos(b));if(id<0 || jumpLatest[id]<=t+h+9){safe=false;break;}
                if(h>=2){double danger=0;for(int j=0;j<NMODEL;j++)danger+=e.weight[j]*std::min(3200.,(pos(b)-e.path[j][h]).len());near=std::min(near,danger);clearance+=danger;}
            }
            if(!safe)continue;
            double score=near+.20*clearance+.18*(pos(b)-foe).len()+.22*(me-pos(b)).len()-.16*(pos(b)-home).len();
            if(d.st==D_GROUND)score-=.22*(pos(b)-pos(d)).len();
            if(score>best){best=score;escape=dir;}
        }
        if(best>-1e19)a=command(escape);
    }
    // A speculative ground slash freezes our movement through the opponent's
    // next shooting window. Check contact at impact, and keep defensive parries.
    int cutAwayUntil=-1;V cutAway{};
    void checkGroundSlash(const Obs &o,Action &a){
        const int k=duelEnemy;if(n!=2 || k<0 || !info().M().nwave || !o.p[k].vis || !actor[k].valid ||
            o.me().st!=S_FREE || o.my_dart().st!=D_HAND || o.d[k].st!=D_HAND || o.p[k].st!=S_FREE ||
            t==interceptFire || t<=counterUntil || t<=sweepUntil)return;
        const Player &p=o.me();const Actor &e=actor[k];V walk=V{a.mx*.001,a.my*.001};
        if(a.act==A_NONE && t<cutAwayUntil && shortWalk(p,cutAway,3,cf.run_v)){a=command(cutAway);return;}
        if(a.act!=A_MELEE)return;
        V foe=e.path[0][0],line=foe-me;double gap=line.len();if(gap<1900 || gap>5250)return;
        Body stop{p.x,p.y,p.vx,p.vy};int sh=std::min<int>(H,cf.slash_pre);for(int j=1;j<=sh;j++)move(stop,{});
        double mass=0;for(int m=0;m<NMODEL;m++)if((e.path[m][sh]-pos(stop)).len()<=cf.slash_reach+160 && los(pos(stop),e.path[m][sh]))mass+=e.weight[m];
        if(mass>.11)return;
        for(int h=1;h<=sh+1;h++)for(const auto &f:flights[h])if(f.model<7 && f.confidence>.20 && swept(f.a-me,f.b-me)<reach+200)return;
        V ref=(pos(o.p[k])-pos(history[std::max(0,int(t-cf.delay))%HISTORY])).unit();V side=ref.side();if(side.len()<.5)return;
        double best=-1e20;V choice;for(V dir:{side,side*(-1.),walk, (side-line.unit()*.48).unit(), (side*(-1.)-line.unit()*.48).unit()}){
            Body q{p.x,p.y,p.vx,p.vy};bool safe=true;double sc=0;
            double risk=0;
            for(int h=1;h<=5;h++){V before=pos(q);move(q,dir*cf.run_v);
                for(const auto &f:flights[h])if(f.model>=7)risk=std::max(risk,clip((radius+150-swept(f.a-before,f.b-pos(q)))/370.,0,1)*f.confidence);
                int id=index(pos(q));if(id<0 || jumpLatest[id]<=t+h+10){safe=false;break;}
                sc+=std::abs((pos(q)-me).dot(side))*.7+std::min(3400.,(pos(q)-e.path[0][h]).len())*.20;
            }
            if(!safe || risk>0.83)continue;sc-=1200*risk;sc+=260*walk.dot(dir)-.35*(pos(q)-home).len();if(sc>best){best=sc;choice=dir;}
        }
        if(best>-1e19){a=command(choice);cutAway=choice;cutAwayUntil=t+2;}
    }
    // Use the observed recovery timer to bound where a target can be when
    // the dart crosses. Each free tick grows the reachable disc by one step.
    void punishMiss(const Obs &o,Action &a){
        int k=duelEnemy;if(n!=2 || k<0 || !info().M().nwave || !o.p[k].vis || !actor[k].valid || t<cf.delay ||
            o.my_dart().st!=D_HAND || o.me().st!=S_FREE || o.d[k].st!=D_HAND || a.act==A_MELEE)return;
        const auto &e=o.p[k];const auto &p=o.me();if(e.st!=S_SLASH && e.st!=S_SLASHED)return;
        int locked=e.timer+(e.st==S_SLASH?cf.slash_post:0)-cf.delay;if(locked<2)return;
        Body targetStop{e.x,e.y,e.vx,e.vy};for(int j=0;j<cf.delay;j++)move(targetStop,{});
        V foe=pos(targetStop),toward=(foe-me).unit(),walk=V{a.mx*.001,a.my*.001};double gap=(foe-me).len();
        if(gap<1400 || gap>4600)return;
        if(a.act==A_THROW){
            Body original{p.x,p.y,p.vx,p.vy};
            for(int h=0;h<cf.throw_pre;h++)move(original,walk*(cf.run_v*cf.throw_move*.01));
            V start=pos(original),ray=V{double(a.ax),double(a.ay)}.unit(),offset=foe-start;
            if(offset.dot(ray)>0 && std::abs(offset.dot(ray.side()))<radius*.56 && los(start,foe))return;
        }
        double best=-1e9;V aim,bestWalk;
        for(V dir:{walk,toward}){
            if(!shortWalk(p,dir,cf.throw_pre+cf.throw_post,cf.run_v*.55))continue;
            Body b{p.x,p.y,p.vx,p.vy};for(int h=0;h<cf.throw_pre;h++)move(b,dir*(cf.run_v*cf.throw_move*.01));
            V start=pos(b),ray=(foe-start).unit();if(!los(start,foe-ray*std::min(420.,gap*.5)))continue;
            V tip=start;for(int h=cf.throw_pre+1;h<=cf.delay+3;h++){
                V end=tip+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);
                i64 wx,wy;bool wall=seg_wall(live,std::lround(tip.x),std::lround(tip.y),std::lround(end.x),std::lround(end.y),wx,wy);
                if(wall)end={double(wx),double(wy)};double err=swept(tip-foe,end-foe);
                double drift=std::max(0,h-locked)*cf.run_v;
                double margin=radius-err-drift*0.88-std::max(0,h-locked-int(cf.slash_pre))*50.;
                if(margin>best){best=margin;aim=ray;bestWalk=dir;}
                if(wall)break;tip=end;
            }
        }
        if(best>75){a=command(bestWalk,A_THROW,aim);shortRelease=t;}
    }
    // Extrapolate each observed movement to impact, then test the whole flight.
    // The last two trajectories describe an approach that brakes or keeps closing.
    struct WindowShot {V ray{};double score=0,early=0;};
    WindowShot windowShot(const Obs &o,int k,V origin,bool pressing){
        const Actor &e=actor[k];V axis=(me-e.oldpos).unit();
        int frame=std::max<int>(0,t-cf.delay);V drift=e.oldvel;
        auto &last=trail[k][std::max(0,frame-4)%TRAIL];
        if(frame>=4 && last.frame==frame-4)drift=(e.oldpos-last.p)*.25;
        V path[3][11];Body b[3];
        for(auto &u:b)u={o.p[k].x,o.p[k].y,o.p[k].vx,o.p[k].vy};
        for(int h=-int(cf.delay);h<=10;h++){
            for(int j=0;j<3;j++){
                if(h>=0)path[j][h]=pos(b[j]);
                V v=drift;
                if(j!=0){V line=me-pos(b[j]);v=line.unit()*clip(line.len()-(j==1?1670.:850.),0.,cf.run_v);}
                move(b[j],v);
            }
        }
        WindowShot best;
        for(int z=-9;z<=9;z++){
            double angle=z*.065;V base=(e.oldpos-origin).unit();V ray=base*std::cos(angle)+base.side()*std::sin(angle);
            V start=origin;double hits[NMODEL+3]{},fast[NMODEL+3]{};
            int horizon=std::min<int>(10,cf.throw_pre+7);
            for(int h=cf.throw_pre+1;h<=horizon;h++){
                V end=start+ray*std::max<i64>(cf.dart_vmin,cf.dart_v-(h-cf.throw_pre-1)*cf.dart_dec);
                i64 x,y;bool wall=seg_wall(live,std::lround(start.x),std::lround(start.y),std::lround(end.x),std::lround(end.y),x,y);
                if(wall)end={double(x),double(y)};
                for(int j=0;j<NMODEL+3;j++){
                    const V *route=j<NMODEL?e.path[j]:path[j-NMODEL];
                    double miss=swept(start-route[h-1],end-route[h]);
                    double contact=clip((radius+90-miss)/300.,0,1);
                    int first=cf.delay+1;double excess=std::max<double>(0,h-first);
                    double escape=excess*cf.run_v*.73;
                    double sure=clip((radius+90-miss-escape)/300.,0,1);
                    hits[j]=std::max(hits[j],contact);fast[j]=std::max(fast[j],sure);
                }
                start=end;if(wall)break;
            }
            double q=0,early=0;double prior=pressing?.52:0.;
            for(int j=0;j<NMODEL+3;j++){
                double w=j<NMODEL?(1-prior)*e.weight[j]:prior*(j==NMODEL?.32:j==NMODEL+1?.44:.24);
                q+=w*hits[j];early+=w*fast[j];
            }
            double score=.22*q+.78*early;if(score>best.score)best={ray,score,early};
        }return best;
    }
